/* Source: supplied MXMGR task inventory, 100 Skills draft, FLUX notes; proposed curriculum. */
window.FMTaskMapData={"version":"2026-11-18","title":"Force Multiplier — MXMGR Fundamentals Task Map","categories":[{"id":"scheduling","name":"Scheduling","description":"Turn flying and maintenance requirements into a feasible, coordinated plan.","sections":["fgs_scheduling","wing_scheduling"],"color":"#1f5aa9"},{"id":"documentation","name":"Documentation","description":"Protect maintenance requirements, applicability, configuration and completion evidence.","sections":["fgs_documentation","wing_documentation"],"color":"#aa249d"},{"id":"analysis","name":"Analysis","description":"Turn trustworthy maintenance data into commander decisions.","sections":["fgs_analysis","wing_analysis"],"color":"#1f5aa9"},{"id":"engine","name":"Engine Management","description":"Know the status, planned work and risk of every controlled engine.","sections":["engine"],"color":"#a64b1e"},{"id":"dit_dbm","name":"Data Integrity / DBM","description":"Make records trustworthy and keep systems correctly accessible.","sections":["dit_dbm"],"color":"#ac239d"}],"sections":[{"id":"fgs_scheduling","title":"FGS Scheduling","color":"#1f5aa9","kind":"fgs"},{"id":"wing_scheduling","title":"Wing Scheduling","color":"#17637e","kind":"wing"},{"id":"fgs_documentation","title":"FGS Documentation","color":"#aa249d","kind":"fgs"},{"id":"wing_documentation","title":"Wing Documentation","color":"#aa249d","kind":"wing"},{"id":"fgs_analysis","title":"FGS Analysis","color":"#1f5aa9","kind":"fgs"},{"id":"wing_analysis","title":"Wing Analysis","color":"#17637e","kind":"wing"},{"id":"engine","title":"Engine Management","color":"#9b4515","kind":"fgs"},{"id":"dit_dbm","title":"Data Integrity / DBM","color":"#ae249d","kind":"fgs"}],"tasks":[{"id":"fgs_scheduling-01","section":"fgs_scheduling","group":"FGS Scheduling","discipline":"scheduling","color":"#1f5aa9","title":"Checkerboard: Weekly, Monthly, Long Range","moduleArea":"scheduling","moduleId":"checkerboard","definition":"Integrate flying demand and all known maintenance into one feasible aircraft-by-day plan; see which work should be consolidated.","proof":"Build and brief an executable 90-day aircraft-by-day checkerboard for a synthetic fleet; demonstrate one valid downtime consolidation, one disruption recovery, and a traceable record of limitations and approvals.","pitfall":"Treating a checkerboard as colored boxes instead of a capacity-constrained decision tool; bundling tasks without validating tech data; double-booking a dock; scheduling NMC, Phase, HQ-restricted or depot aircraft as flyers.","scenario":"Two paint actions and an inspection are due in the same period; compare separate downtime to an authorized consolidated window.","fundamentals":["Translate annual FHP into quarterly, monthly, weekly, and daily sorties and flying hours. Know the mission, turns, spares, utilization and realistic turnaround constraints.","Start with accurate aircraft status, mission capability, configuration, upcoming TCI/TCTO/SI/calendar events, Phase hours, PDM/depot, engine work and overdue items.","Establish workable capacity: maintenance personnel and qualifications, shops, test equipment, hangar/dock space, parts/ETICs, holidays, local flying windows and coordination requirements.","Plot each tail across the planned period using standardized codes; distinguish confirmed maintenance, forecasts, assumptions and unavailable or restricted aircraft.","Consolidate compatible inspections and modifications into shared downtime windows when instructions and resources allow. Respect sequence, safety, cure/hold times and approvals; do not erase required work.","Balance Phase flow, aircraft rotation and Hangar Queen risk; do not hide future downtime to make the current week look better.","Resolve overlaps and bottlenecks, protect spares, and show shortfalls/options before the schedule is approved by the proper authority.","Publish a controlled approved baseline. During execution, log deviations, apply authorized changes, reconcile sorties/work accomplished and update the next forecast."],"related":[{"id":"S01","name":"Translate requirements across planning horizons","proof":"Convert annual, quarterly, monthly, or weekly requirements into daily demand; reconcile the detailed schedule with required output rather than treating each planning period as a separate skill."},{"id":"S02","name":"Establish the planning picture and constraints","proof":"Verify availability, requirements, source dates, and estimates; distinguish confirmed facts, assumptions, mandatory limits, and negotiable preferences before allocating work."},{"id":"S06","name":"Build an integrated schedule","proof":"Build a checkerboard showing flying, reserve, maintenance, and unavailable periods; synchronize people, aircraft, tools, space, and capacity without conflicting assignments."},{"id":"S08","name":"Find and use genuine scheduling opportunities","proof":"Inspect idle windows and holes; fit eligible work after checking duration, dependencies, capability, and resources, and recognize when a gap must remain unfilled."},{"id":"S09","name":"Combine compatible work and reduce setup","proof":"Compare bundles and sequences that reduce repeated access, setup, changeovers, downtime, or cure only when supplied instructions permit; preserve every requirement and verify the actual time or capacity saved."}],"mission":1,"advanced":"scheduling:skill7","refNames":["CAFI 21-165 (historical CAF scheduling)","AFI 21-101 ACCSUP Ch. 14","DAFI 21-101 Ch. 5 and Ch. 14"],"status":"source-based + working-group synthesis (not official certification)"},{"id":"fgs_scheduling-02","section":"fgs_scheduling","group":"FGS Scheduling","discipline":"scheduling","color":"#1f5aa9","title":"AVDO / PIC Changes","moduleArea":"scheduling","moduleId":"control","definition":"Maintain accountable aircraft possession and in-commission status when aircraft arrive, depart, or change reporting responsibility.","proof":"Reconcile the approved inventory change, effective time, new status, and affected planning/reporting totals.","pitfall":"Treating a reported move as completed without the approved transfer or effective-date evidence.","scenario":"An aircraft transfers midmonth while the schedule and utilization totals still show it as possessed.","fundamentals":["Record the approver, current schedule version and controlled changes.","Reconcile sorties, flying hours, aircraft utilization and maintenance completion against plan.","Explain variances, emerging risks, and what the next cycle must change."],"related":[{"id":"S19","name":"Obtain approval and control the approved schedule","proof":"Present the feasible schedule and unresolved exceptions to the designated authority; verify signatures and version, publish the approved schedule, and route subsequent changes through the required approval process."},{"id":"S20","name":"Reconcile execution and improve the next plan","proof":"Compare delivered output, actual duration, usage, and downtime with the approved plan; investigate differences, retain unresolved explanations, and carry justified corrections into the next planning cycle."}],"mission":1,"advanced":"scheduling:skill8","refNames":["CAFI 21-165 (historical CAF scheduling)","AFI 21-101 ACCSUP Ch. 14","DAFI 21-101 Ch. 5 and Ch. 14"],"status":"source-based + working-group synthesis (not official certification)"},{"id":"fgs_scheduling-03","section":"fgs_scheduling","group":"FGS Scheduling","discipline":"scheduling","color":"#1f5aa9","title":"AF Forms 2407 / 2410","moduleArea":"scheduling","moduleId":"control","definition":"Interpret and reconcile the legacy forms/data products identified in the unit task list; verify the current authorized equivalent before teaching field-level procedures.","proof":"Locate the authoritative procedure, identify required fields, validate dates and totals, and show what record changed.","pitfall":"Assuming a historical form name guarantees the same current workflow or inventing its purpose.","scenario":"A supervisor finds mismatched figures on a legacy scheduling report and the system of record.","fundamentals":["Record the approver, current schedule version and controlled changes.","Reconcile sorties, flying hours, aircraft utilization and maintenance completion against plan.","Explain variances, emerging risks, and what the next cycle must change."],"related":[{"id":"S19","name":"Obtain approval and control the approved schedule","proof":"Present the feasible schedule and unresolved exceptions to the designated authority; verify signatures and version, publish the approved schedule, and route subsequent changes through the required approval process."},{"id":"S20","name":"Reconcile execution and improve the next plan","proof":"Compare delivered output, actual duration, usage, and downtime with the approved plan; investigate differences, retain unresolved explanations, and carry justified corrections into the next planning cycle."}],"mission":1,"advanced":"scheduling:skill8","refNames":["CAFI 21-165 (historical CAF scheduling)","AFI 21-101 ACCSUP Ch. 14","DAFI 21-101 Ch. 5 and Ch. 14"],"status":"source-based + working-group synthesis (not official certification)"},{"id":"fgs_scheduling-04","section":"fgs_scheduling","group":"FGS Scheduling","discipline":"scheduling","color":"#1f5aa9","title":"Pre-Documentation Meetings","moduleArea":"scheduling","moduleId":"recover","definition":"Prepare decisions before the formal scheduling meeting, not merely a slide deck.","proof":"Bring demand, known conflicts, parts, manpower and aircraft capability; leave with assigned actions and suspense dates.","pitfall":"Meeting without source information, decisions, owners or follow-up.","scenario":"Operations requests two extra sorties; Production identifies a late critical part before the weekly plan is approved.","fundamentals":["Identify exactly what changed: ETIC, part arrival, mission demand, manpower or aircraft status.","Recompute what can fly, what can be maintained and what must move; distinguish feasible from desired output.","Coordinate with Production, Operations, MOC and specialists; capture alternatives, owners and due actions."],"related":[{"id":"S17","name":"Recover a disrupted schedule","proof":"After an outage, late part, changed requirement, or duration overrun, trace dependencies, test contingencies, restore feasibility, and communicate necessary changes while preserving unaffected commitments."},{"id":"S18","name":"Run a scheduling meeting that produces decisions","proof":"Prepare the plan and unresolved issues, reconcile stakeholder requirements, surface conflicts, record decisions and tradeoffs, and assign owners, deadlines, and follow-up actions."}],"mission":2,"advanced":"scheduling:skill8","refNames":["CAFI 21-165 (historical CAF scheduling)","AFI 21-101 ACCSUP Ch. 14","DAFI 21-101 Ch. 5 and Ch. 14"],"status":"source-based + working-group synthesis (not official certification)"},{"id":"fgs_scheduling-05","section":"fgs_scheduling","group":"FGS Scheduling","discipline":"scheduling","color":"#1f5aa9","title":"AFTO Form 103","moduleArea":"scheduling","moduleId":"control","definition":"Recognize when the locally identified AFTO 103 record is applicable and verify completion against current form instructions and source evidence.","proof":"Show correct source, reconciliation and routing for a fictional case without assuming older form procedures still apply.","pitfall":"Transcribing a value without checking its definition, effective period and controlled reference.","scenario":"The published form and system entry disagree on an asset's recorded utilization.","fundamentals":["Record the approver, current schedule version and controlled changes.","Reconcile sorties, flying hours, aircraft utilization and maintenance completion against plan.","Explain variances, emerging risks, and what the next cycle must change."],"related":[{"id":"S19","name":"Obtain approval and control the approved schedule","proof":"Present the feasible schedule and unresolved exceptions to the designated authority; verify signatures and version, publish the approved schedule, and route subsequent changes through the required approval process."},{"id":"S20","name":"Reconcile execution and improve the next plan","proof":"Compare delivered output, actual duration, usage, and downtime with the approved plan; investigate differences, retain unresolved explanations, and carry justified corrections into the next planning cycle."}],"mission":1,"advanced":"scheduling:skill8","refNames":["CAFI 21-165 (historical CAF scheduling)","AFI 21-101 ACCSUP Ch. 14","DAFI 21-101 Ch. 5 and Ch. 14"],"status":"source-based + working-group synthesis (not official certification)"},{"id":"fgs_scheduling-06","section":"fgs_scheduling","group":"FGS Scheduling","discipline":"scheduling","color":"#1f5aa9","title":"Overdues / Missing / Wrong Entries","moduleArea":"scheduling","moduleId":"planned","definition":"Find maintenance requirements that are overdue, absent, duplicated or incorrectly coded before they distort the schedule.","proof":"Create a prioritized exception list with source, due point, impact, owner and required correction/escalation.","pitfall":"Silently erasing or postponing overdue work.","scenario":"A weekly checkerboard omits a time-change requirement that becomes due Thursday.","fundamentals":["Identify inspection, TCI, TCTO and modification due windows and the correct operating-hour or calendar clock.","Check prerequisite parts, qualified labor, tools, dock capacity and work sequence.","Place work before the due point; combine related jobs when approved, including necessary curing and reassembly.","Commit planned downtime only after checking readiness; maintain a record of why it was scheduled."],"related":[{"id":"S07","name":"Sequence work using the correct clocks and deadlines","proof":"Work backward through prerequisites, execution, staffed calendars, elapsed waiting, cure, and verification; calculate feasible start and finish times, the latest feasible start, and remaining scheduling margin."},{"id":"S10","name":"Plan modifications and other one-time work","proof":"Build a modification schedule across affected aircraft; establish applicability, prerequisites, parts readiness, staffing, facilities, duration, cure, deadlines, and return-to-service conditions."},{"id":"S11","name":"Plan inspections and other recurring work","proof":"Forecast inspection or renewal due points from verified dates or usage; assign feasible slots within permitted windows and smooth clustered demand while maintaining operational coverage."},{"id":"S12","name":"Request and stage parts and materials","proof":"Identify required modification parts and quantities, calculate need-by dates, submit or route the authorized order, track delivery evidence, and update readiness assumptions when estimates change."},{"id":"S13","name":"Commit downtime when prerequisites are ready","proof":"Check parts, information, approvals, personnel, facilities, and predecessor work before starting; stage missing prerequisites or explain a justified early commitment under the supplied constraints."}],"mission":4,"advanced":"doc:home","refNames":["CAFI 21-165 (historical CAF scheduling)","AFI 21-101 ACCSUP Ch. 14","DAFI 21-101 Ch. 5 and Ch. 14"],"status":"source-based + working-group synthesis (not official certification)"},{"id":"fgs_scheduling-07","section":"fgs_scheduling","group":"FGS Scheduling","discipline":"scheduling","color":"#1f5aa9","title":"Flying Hour Program (FHP)","moduleArea":"scheduling","moduleId":"checkerboard","definition":"Translate annual flying-hour goals through quarterly, monthly, weekly and daily flying requirements.","proof":"Reconcile projected versus flown hours and sorties; identify reflow required by capability and priorities.","pitfall":"Treating the annual target as a daily sortie requirement without utilization and maintenance checks.","scenario":"A month is underflown by 12 hours and two aircraft enter Phase next week.","fundamentals":["Convert annual, monthly and weekly flying requirements into daily demand and required availability.","Mark known downtime, overdue or approaching inspections, Phase windows, depot moves, NMC status, manpower, parts and facilities.","Find usable maintenance opportunities; group work that can share access, downtime or setup without violating instructions.","Condense compatible PFR and PBG work so a common cure happens once only when authorized. Preserve two workdays per task and a full 24-hour cure."],"related":[{"id":"S01","name":"Translate requirements across planning horizons","proof":"Convert annual, quarterly, monthly, or weekly requirements into daily demand; reconcile the detailed schedule with required output rather than treating each planning period as a separate skill."},{"id":"S02","name":"Establish the planning picture and constraints","proof":"Verify availability, requirements, source dates, and estimates; distinguish confirmed facts, assumptions, mandatory limits, and negotiable preferences before allocating work."},{"id":"S06","name":"Build an integrated schedule","proof":"Build a checkerboard showing flying, reserve, maintenance, and unavailable periods; synchronize people, aircraft, tools, space, and capacity without conflicting assignments."},{"id":"S08","name":"Find and use genuine scheduling opportunities","proof":"Inspect idle windows and holes; fit eligible work after checking duration, dependencies, capability, and resources, and recognize when a gap must remain unfilled."},{"id":"S09","name":"Combine compatible work and reduce setup","proof":"Compare bundles and sequences that reduce repeated access, setup, changeovers, downtime, or cure only when supplied instructions permit; preserve every requirement and verify the actual time or capacity saved."}],"mission":1,"advanced":"scheduling:skill7","refNames":["CAFI 21-165 (historical CAF scheduling)","AFI 21-101 ACCSUP Ch. 14","DAFI 21-101 Ch. 5 and Ch. 14"],"status":"source-based + working-group synthesis (not official certification)"},{"id":"fgs_scheduling-08","section":"fgs_scheduling","group":"FGS Scheduling","discipline":"scheduling","color":"#1f5aa9","title":"Document Reviews","moduleArea":"scheduling","moduleId":"control","definition":"Verify schedule-related records and source documentation before decisions are published.","proof":"Find inconsistencies between approved requirement, system entry and published scheduling page; route corrections.","pitfall":"Approving a schedule built on stale status or unsupported entries.","scenario":"The local schedule shows FMC but the current maintenance source lists a restriction.","fundamentals":["Record the approver, current schedule version and controlled changes.","Reconcile sorties, flying hours, aircraft utilization and maintenance completion against plan.","Explain variances, emerging risks, and what the next cycle must change."],"related":[{"id":"S19","name":"Obtain approval and control the approved schedule","proof":"Present the feasible schedule and unresolved exceptions to the designated authority; verify signatures and version, publish the approved schedule, and route subsequent changes through the required approval process."},{"id":"S20","name":"Reconcile execution and improve the next plan","proof":"Compare delivered output, actual duration, usage, and downtime with the approved plan; investigate differences, retain unresolved explanations, and carry justified corrections into the next planning cycle."}],"mission":1,"advanced":"scheduling:skill8","refNames":["CAFI 21-165 (historical CAF scheduling)","AFI 21-101 ACCSUP Ch. 14","DAFI 21-101 Ch. 5 and Ch. 14"],"status":"source-based + working-group synthesis (not official certification)"},{"id":"fgs_scheduling-09","section":"fgs_scheduling","group":"FGS Scheduling","discipline":"scheduling","color":"#1f5aa9","title":"Pulled Forms","moduleArea":"scheduling","moduleId":"control","definition":"Collect and track source forms/records that were removed for review or action so no requirement disappears.","proof":"Maintain custody, reason, suspense, and proof of return/replacement or approved correction.","pitfall":"Losing document history or using an untracked working copy as authoritative.","scenario":"A required controlled record is pulled for correction while the weekly plan is being finalized.","fundamentals":["Record the approver, current schedule version and controlled changes.","Reconcile sorties, flying hours, aircraft utilization and maintenance completion against plan.","Explain variances, emerging risks, and what the next cycle must change."],"related":[{"id":"S19","name":"Obtain approval and control the approved schedule","proof":"Present the feasible schedule and unresolved exceptions to the designated authority; verify signatures and version, publish the approved schedule, and route subsequent changes through the required approval process."},{"id":"S20","name":"Reconcile execution and improve the next plan","proof":"Compare delivered output, actual duration, usage, and downtime with the approved plan; investigate differences, retain unresolved explanations, and carry justified corrections into the next planning cycle."}],"mission":1,"advanced":"scheduling:skill8","refNames":["CAFI 21-165 (historical CAF scheduling)","AFI 21-101 ACCSUP Ch. 14","DAFI 21-101 Ch. 5 and Ch. 14"],"status":"source-based + working-group synthesis (not official certification)"},{"id":"fgs_scheduling-10","section":"fgs_scheduling","group":"FGS Scheduling","discipline":"scheduling","color":"#1f5aa9","title":"Load Sorties","moduleArea":"scheduling","moduleId":"daily","definition":"Correctly enter and reconcile authorized flying demand, including first wave, turns, spares and planned utilization.","proof":"Match sorties to tail, date, authorized schedule version, mission needs and realistic aircraft/turn capability.","pitfall":"Double-loading a tail or counting an unauthorized sortie as approved demand.","scenario":"Six first-wave aircraft must produce four turns, but one goes NMC before launch.","fundamentals":["Read the aircraft-by-aircraft status and configuration; identify required mission/turn capability.","Select six FMC first-wave aircraft; choose four of those aircraft for turns.","For larger requirements, schedule 12 first-wave aircraft plus ten turns and protect the designated spare.","Recheck the lineup after an aircraft abort, NMC change or priority mission."],"related":[{"id":"S03","name":"Match capable resources to the assignment","proof":"Select six eligible first-go aircraft and four feasible turn aircraft in a 6-turn-4 exercise; satisfy capability, configuration, turnaround, usage, and support constraints, preserving scarce capabilities for work that needs them."},{"id":"S04","name":"Plan spares and contingencies","proof":"Select an eligible spare or capacity margin, test credible duration and arrival delays, and place buffers or contingencies without double-counting resources or concealing a shortfall."}],"mission":1,"advanced":"scheduling:skill1","refNames":["CAFI 21-165 (historical CAF scheduling)","AFI 21-101 ACCSUP Ch. 14","DAFI 21-101 Ch. 5 and Ch. 14"],"status":"source-based + working-group synthesis (not official certification)"},{"id":"fgs_scheduling-11","section":"fgs_scheduling","group":"FGS Scheduling","discipline":"scheduling","color":"#1f5aa9","title":"Phase Flow","moduleArea":"scheduling","moduleId":"phase","definition":"Forecast recurring inspection entry using hours remaining, projected utilization and available dock capacity.","proof":"Show hours remaining by tail, forecast week/dock entry, expected downtime and impact of each flying choice.","pitfall":"Flying only the closest-to-Phase aircraft or overusing high-hour aircraft until the rest become hangar queens.","scenario":"Two tails approach Phase with one available dock; rebalance usage without creating an HQ.","fundamentals":["Read hours remaining to Phase for every eligible aircraft and anticipate use in the next period.","Estimate expected hours burned by first-wave and turn decisions; identify clusters approaching the limit.","Balance low-hour and high-hour aircraft and protect the aircraft approaching 30 days without flying.","Explain the capacity effect if two aircraft become due together."],"related":[{"id":"S05","name":"Manage utilization and prevent prolonged inactivity","proof":"Track use and time since last use; rotate eligible aircraft or plan recovery before the supplied non-use threshold, avoiding a hangar queen while preserving mission capability and required reserves."},{"id":"S15","name":"Balance utilization and recurring workload","proof":"Build and fix phase flow by projecting hours, cycles, and due points against dock capacity; rebalance permitted utilization or inspection entries. Apply the same cumulative-use logic to other allowances and inventory."}],"mission":3,"advanced":"scheduling:skill4","refNames":["CAFI 21-165 (historical CAF scheduling)","AFI 21-101 ACCSUP Ch. 14","DAFI 21-101 Ch. 5 and Ch. 14"],"status":"source-based + working-group synthesis (not official certification)"},{"id":"wing_scheduling-01","section":"wing_scheduling","group":"Wing Scheduling","discipline":"scheduling","color":"#17637e","title":"Wing AVDO","moduleArea":"scheduling","moduleId":"control","definition":"Reconcile wing aircraft inventory, possession, status and accountable reporting changes across units.","proof":"Prepare a source-supported wing inventory/status view tied to actual effective dates and approvals.","pitfall":"Summing unit counts without reconciling transfers, deployed assets or time periods.","scenario":"Two units both count an aircraft during its transfer week.","fundamentals":["Record the approver, current schedule version and controlled changes.","Reconcile sorties, flying hours, aircraft utilization and maintenance completion against plan.","Explain variances, emerging risks, and what the next cycle must change."],"related":[{"id":"S19","name":"Obtain approval and control the approved schedule","proof":"Present the feasible schedule and unresolved exceptions to the designated authority; verify signatures and version, publish the approved schedule, and route subsequent changes through the required approval process."},{"id":"S20","name":"Reconcile execution and improve the next plan","proof":"Compare delivered output, actual duration, usage, and downtime with the approved plan; investigate differences, retain unresolved explanations, and carry justified corrections into the next planning cycle."}],"mission":1,"advanced":"scheduling:skill8","refNames":["CAFI 21-165 (historical CAF scheduling)","AFI 21-101 ACCSUP Ch. 14","DAFI 21-101 Ch. 5 and Ch. 14"],"status":"source-based + working-group synthesis (not official certification)"},{"id":"wing_scheduling-02","section":"wing_scheduling","group":"Wing Scheduling","discipline":"scheduling","color":"#17637e","title":"Maintenance Scheduling Effectiveness (MSE)","moduleArea":"scheduling","moduleId":"control","definition":"Measure whether scheduled maintenance was accomplished as planned and explain the drivers of deviations.","proof":"Compute an appropriate MSE result from defined scheduled/accomplished events and classify deviations against the controlling rule.","pitfall":"Changing the denominator or excluding misses to improve a headline rate.","scenario":"Five planned events slipped because of parts; distinguish schedulable and uncontrollable causes.","fundamentals":["Record the approver, current schedule version and controlled changes.","Reconcile sorties, flying hours, aircraft utilization and maintenance completion against plan.","Explain variances, emerging risks, and what the next cycle must change."],"related":[{"id":"S19","name":"Obtain approval and control the approved schedule","proof":"Present the feasible schedule and unresolved exceptions to the designated authority; verify signatures and version, publish the approved schedule, and route subsequent changes through the required approval process."},{"id":"S20","name":"Reconcile execution and improve the next plan","proof":"Compare delivered output, actual duration, usage, and downtime with the approved plan; investigate differences, retain unresolved explanations, and carry justified corrections into the next planning cycle."}],"mission":1,"advanced":"scheduling:skill8","refNames":["CAFI 21-165 (historical CAF scheduling)","AFI 21-101 ACCSUP Ch. 14","DAFI 21-101 Ch. 5 and Ch. 14"],"status":"source-based + working-group synthesis (not official certification)"},{"id":"wing_scheduling-03","section":"wing_scheduling","group":"Wing Scheduling","discipline":"scheduling","color":"#17637e","title":"SUTE / Utilization","moduleArea":"scheduling","moduleId":"checkerboard","definition":"Monitor utilization trends and verify what the locally used SUTE label denotes in the current reporting source.","proof":"Reconcile source flying data, time periods and forecast utilization against mission and maintenance limits.","pitfall":"Using an unverified legacy acronym or mismatching hours, sorties and inventory populations.","scenario":"A projection looks on target but one tail is carrying most of the flying hours.","fundamentals":["Convert annual, monthly and weekly flying requirements into daily demand and required availability.","Mark known downtime, overdue or approaching inspections, Phase windows, depot moves, NMC status, manpower, parts and facilities.","Find usable maintenance opportunities; group work that can share access, downtime or setup without violating instructions.","Condense compatible PFR and PBG work so a common cure happens once only when authorized. Preserve two workdays per task and a full 24-hour cure."],"related":[{"id":"S01","name":"Translate requirements across planning horizons","proof":"Convert annual, quarterly, monthly, or weekly requirements into daily demand; reconcile the detailed schedule with required output rather than treating each planning period as a separate skill."},{"id":"S02","name":"Establish the planning picture and constraints","proof":"Verify availability, requirements, source dates, and estimates; distinguish confirmed facts, assumptions, mandatory limits, and negotiable preferences before allocating work."},{"id":"S06","name":"Build an integrated schedule","proof":"Build a checkerboard showing flying, reserve, maintenance, and unavailable periods; synchronize people, aircraft, tools, space, and capacity without conflicting assignments."},{"id":"S08","name":"Find and use genuine scheduling opportunities","proof":"Inspect idle windows and holes; fit eligible work after checking duration, dependencies, capability, and resources, and recognize when a gap must remain unfilled."},{"id":"S09","name":"Combine compatible work and reduce setup","proof":"Compare bundles and sequences that reduce repeated access, setup, changeovers, downtime, or cure only when supplied instructions permit; preserve every requirement and verify the actual time or capacity saved."}],"mission":1,"advanced":"scheduling:skill7","refNames":["CAFI 21-165 (historical CAF scheduling)","AFI 21-101 ACCSUP Ch. 14","DAFI 21-101 Ch. 5 and Ch. 14"],"status":"source-based + working-group synthesis (not official certification)"},{"id":"wing_scheduling-04","section":"wing_scheduling","group":"Wing Scheduling","discipline":"scheduling","color":"#17637e","title":"First Look","moduleArea":"scheduling","moduleId":"capacity","definition":"Build a credible early view of next-period ability to generate the required flying effort.","proof":"Crosscheck aircraft capability, maintenance demand, labor, parts, facilities, Phase and priority commitments.","pitfall":"Announcing a requirement can be met without resource or fleet-status evidence.","scenario":"The commander asks whether 12 sorties are realistic next week before all ETICs are firm.","fundamentals":["Map bottlenecks: inspection docks, specialist labor, tools, parts, facility restrictions and shared assets.","Preserve required reserves, dependencies and protected windows; identify donor/recovery effects when an aircraft is unavailable.","Quantify the mission impact of moving work and offer choices when demand exceeds capacity."],"related":[{"id":"S14","name":"Plan use and recovery of unavailable resources","proof":"In a cann-bird case with multiple parts delays, compare keeping, recovering, or using an eligible donor; assess total capability, required authority, added work, parts dependencies, and the donor recovery plan."},{"id":"S16","name":"Protect bottlenecks and make capacity tradeoffs","proof":"Identify the resource limiting output; compare feasible allocations against stated priorities and report the system-wide gain, unmet demand, displaced work, and consequences."}],"mission":3,"advanced":"scheduling:skill8","refNames":["CAFI 21-165 (historical CAF scheduling)","AFI 21-101 ACCSUP Ch. 14","DAFI 21-101 Ch. 5 and Ch. 14"],"status":"source-based + working-group synthesis (not official certification)"},{"id":"wing_scheduling-05","section":"wing_scheduling","group":"Wing Scheduling","discipline":"scheduling","color":"#17637e","title":"Static Display","moduleArea":"scheduling","moduleId":"planned","definition":"Coordinate temporary loss of aircraft availability and associated approvals for static-display missions.","proof":"Capture authorized requirement, schedule window, configuration, transfer needs and return-to-fly impacts.","pitfall":"Treating a display aircraft as an available flying spare.","scenario":"A flying aircraft is requested for a three-day event overlapping a Phase input.","fundamentals":["Identify inspection, TCI, TCTO and modification due windows and the correct operating-hour or calendar clock.","Check prerequisite parts, qualified labor, tools, dock capacity and work sequence.","Place work before the due point; combine related jobs when approved, including necessary curing and reassembly.","Commit planned downtime only after checking readiness; maintain a record of why it was scheduled."],"related":[{"id":"S07","name":"Sequence work using the correct clocks and deadlines","proof":"Work backward through prerequisites, execution, staffed calendars, elapsed waiting, cure, and verification; calculate feasible start and finish times, the latest feasible start, and remaining scheduling margin."},{"id":"S10","name":"Plan modifications and other one-time work","proof":"Build a modification schedule across affected aircraft; establish applicability, prerequisites, parts readiness, staffing, facilities, duration, cure, deadlines, and return-to-service conditions."},{"id":"S11","name":"Plan inspections and other recurring work","proof":"Forecast inspection or renewal due points from verified dates or usage; assign feasible slots within permitted windows and smooth clustered demand while maintaining operational coverage."},{"id":"S12","name":"Request and stage parts and materials","proof":"Identify required modification parts and quantities, calculate need-by dates, submit or route the authorized order, track delivery evidence, and update readiness assumptions when estimates change."},{"id":"S13","name":"Commit downtime when prerequisites are ready","proof":"Check parts, information, approvals, personnel, facilities, and predecessor work before starting; stage missing prerequisites or explain a justified early commitment under the supplied constraints."}],"mission":4,"advanced":"doc:home","refNames":["CAFI 21-165 (historical CAF scheduling)","AFI 21-101 ACCSUP Ch. 14","DAFI 21-101 Ch. 5 and Ch. 14"],"status":"source-based + working-group synthesis (not official certification)"},{"id":"wing_scheduling-06","section":"wing_scheduling","group":"Wing Scheduling","discipline":"scheduling","color":"#17637e","title":"FHP / Flying Program","moduleArea":"scheduling","moduleId":"checkerboard","definition":"Translate and reconcile wing flying requirements with actual aircraft and maintenance capacity; normalize earlier 'FGP' shorthand to FHP.","proof":"Show annual-to-daily reflow with gap, maintenance impact, options and decision authority.","pitfall":"Forcing wing totals to match a target with no executable tail-by-tail plan.","scenario":"Operations adds a training requirement that would exceed the month’s usable sortie capacity.","fundamentals":["Convert annual, monthly and weekly flying requirements into daily demand and required availability.","Mark known downtime, overdue or approaching inspections, Phase windows, depot moves, NMC status, manpower, parts and facilities.","Find usable maintenance opportunities; group work that can share access, downtime or setup without violating instructions.","Condense compatible PFR and PBG work so a common cure happens once only when authorized. Preserve two workdays per task and a full 24-hour cure."],"related":[{"id":"S01","name":"Translate requirements across planning horizons","proof":"Convert annual, quarterly, monthly, or weekly requirements into daily demand; reconcile the detailed schedule with required output rather than treating each planning period as a separate skill."},{"id":"S02","name":"Establish the planning picture and constraints","proof":"Verify availability, requirements, source dates, and estimates; distinguish confirmed facts, assumptions, mandatory limits, and negotiable preferences before allocating work."},{"id":"S06","name":"Build an integrated schedule","proof":"Build a checkerboard showing flying, reserve, maintenance, and unavailable periods; synchronize people, aircraft, tools, space, and capacity without conflicting assignments."},{"id":"S08","name":"Find and use genuine scheduling opportunities","proof":"Inspect idle windows and holes; fit eligible work after checking duration, dependencies, capability, and resources, and recognize when a gap must remain unfilled."},{"id":"S09","name":"Combine compatible work and reduce setup","proof":"Compare bundles and sequences that reduce repeated access, setup, changeovers, downtime, or cure only when supplied instructions permit; preserve every requirement and verify the actual time or capacity saved."}],"mission":1,"advanced":"scheduling:skill7","refNames":["CAFI 21-165 (historical CAF scheduling)","AFI 21-101 ACCSUP Ch. 14","DAFI 21-101 Ch. 5 and Ch. 14"],"status":"source-based + working-group synthesis (not official certification)"},{"id":"wing_scheduling-07","section":"wing_scheduling","group":"Wing Scheduling","discipline":"scheduling","color":"#17637e","title":"Hangar Utilization","moduleArea":"scheduling","moduleId":"capacity","definition":"Allocate hangar bays, docks, specialized tooling and labor across competing maintenance work.","proof":"Produce a feasible facility-loading plan with dates, capacity, work length and contingencies.","pitfall":"Double-booking one dock or assuming a resource is interchangeable.","scenario":"Phase, aircraft paint and engine work all request the same facility on Tuesday.","fundamentals":["Map bottlenecks: inspection docks, specialist labor, tools, parts, facility restrictions and shared assets.","Preserve required reserves, dependencies and protected windows; identify donor/recovery effects when an aircraft is unavailable.","Quantify the mission impact of moving work and offer choices when demand exceeds capacity."],"related":[{"id":"S14","name":"Plan use and recovery of unavailable resources","proof":"In a cann-bird case with multiple parts delays, compare keeping, recovering, or using an eligible donor; assess total capability, required authority, added work, parts dependencies, and the donor recovery plan."},{"id":"S16","name":"Protect bottlenecks and make capacity tradeoffs","proof":"Identify the resource limiting output; compare feasible allocations against stated priorities and report the system-wide gain, unmet demand, displaced work, and consequences."}],"mission":3,"advanced":"scheduling:skill8","refNames":["CAFI 21-165 (historical CAF scheduling)","AFI 21-101 ACCSUP Ch. 14","DAFI 21-101 Ch. 5 and Ch. 14"],"status":"source-based + working-group synthesis (not official certification)"},{"id":"wing_scheduling-08","section":"wing_scheduling","group":"Wing Scheduling","discipline":"scheduling","color":"#17637e","title":"Depot / PDM","moduleArea":"scheduling","moduleId":"planned","definition":"Plan depot departure, return, transfer, and associated inspection/resource impact in the longer-range schedule.","proof":"Reflect the actual scheduled depot window, inventory effects, return risk and downstream flying-hour reflow.","pitfall":"Scheduling the aircraft to fly while it is scheduled to be away at depot.","scenario":"One aircraft departs for six months and the unit must maintain the flying-hour target.","fundamentals":["Identify inspection, TCI, TCTO and modification due windows and the correct operating-hour or calendar clock.","Check prerequisite parts, qualified labor, tools, dock capacity and work sequence.","Place work before the due point; combine related jobs when approved, including necessary curing and reassembly.","Commit planned downtime only after checking readiness; maintain a record of why it was scheduled."],"related":[{"id":"S07","name":"Sequence work using the correct clocks and deadlines","proof":"Work backward through prerequisites, execution, staffed calendars, elapsed waiting, cure, and verification; calculate feasible start and finish times, the latest feasible start, and remaining scheduling margin."},{"id":"S10","name":"Plan modifications and other one-time work","proof":"Build a modification schedule across affected aircraft; establish applicability, prerequisites, parts readiness, staffing, facilities, duration, cure, deadlines, and return-to-service conditions."},{"id":"S11","name":"Plan inspections and other recurring work","proof":"Forecast inspection or renewal due points from verified dates or usage; assign feasible slots within permitted windows and smooth clustered demand while maintaining operational coverage."},{"id":"S12","name":"Request and stage parts and materials","proof":"Identify required modification parts and quantities, calculate need-by dates, submit or route the authorized order, track delivery evidence, and update readiness assumptions when estimates change."},{"id":"S13","name":"Commit downtime when prerequisites are ready","proof":"Check parts, information, approvals, personnel, facilities, and predecessor work before starting; stage missing prerequisites or explain a justified early commitment under the supplied constraints."}],"mission":4,"advanced":"doc:home","refNames":["CAFI 21-165 (historical CAF scheduling)","AFI 21-101 ACCSUP Ch. 14","DAFI 21-101 Ch. 5 and Ch. 14"],"status":"source-based + working-group synthesis (not official certification)"},{"id":"fgs_documentation-01","section":"fgs_documentation","group":"FGS Documentation","discipline":"documentation","color":"#aa249d","title":"Aircraft Documentation","moduleArea":"documentation","moduleId":"authority","definition":"Keep maintenance requirements and completion records tied to the correct aircraft, configuration, date and source.","proof":"Verify an entry's identity, applicability, work accomplished, status and evidence before accepting completion.","pitfall":"A complete-looking record with the wrong serial number or period.","scenario":"Two aircraft have similar work packages but only one has qualifying accomplishment evidence.","fundamentals":["Find approved instructions and confirm revision, applicability and local supplements.","Translate the text into trigger, asset, due point, action and proof.","Check configuration, serial range, date and exceptions before loading work."],"related":[{"id":"D01","name":"Find the governing reference","proof":"Select the authoritative current instruction; recognize an obsolete, unofficial, or inapplicable substitute."},{"id":"D02","name":"Extract an actionable requirement","proof":"Translate prose into an action, trigger, deadline, responsible role, and evidence requirement."},{"id":"D03","name":"Determine applicability","proof":"Explain why an obligation applies or does not apply to the particular person, asset, configuration, or reporting period."}],"mission":4,"advanced":"doc:term","refNames":["DAFI 21-101 Ch. 5 and Ch. 14","AFI 21-101 ACCSUP Ch. 14"],"status":"source-based + working-group synthesis (not official certification)"},{"id":"fgs_documentation-02","section":"fgs_documentation","group":"FGS Documentation","discipline":"documentation","color":"#aa249d","title":"CAD / PAD","moduleArea":"documentation","moduleId":"forecast","definition":"Track cartridge/propellant-actuated device configuration and controlled life limits using authorized technical data.","proof":"Compare serialized installed items, applicable life/time limits, source history and forecast needed work.","pitfall":"Confusing similar part numbers or copying limits across configurations.","scenario":"A device is replaced with a different approved part number carrying a different life limit.","fundamentals":["Choose the correct calendar, flight-hour, cycle or event-based clock.","Use approved last accomplishment and interval to calculate the next due point.","Check prerequisites, parts, tools and qualification needs before asking Scheduling for downtime."],"related":[{"id":"D04","name":"Establish the due point","proof":"Calculate the deadline from the correct trigger, units, calendar, and authorized rule."},{"id":"D05","name":"Manage recurrence","proof":"Calculate the next obligation from the correct verified accomplishment or other anchor specified in the governing rule."},{"id":"D06","name":"Recognize prerequisites","proof":"Keep a dependent action open when the required predecessor or supporting evidence has not been established."}],"mission":4,"advanced":"doc:inspection","refNames":["DAFI 21-101 Ch. 5 and Ch. 14","AFI 21-101 ACCSUP Ch. 14"],"status":"source-based + working-group synthesis (not official certification)"},{"id":"fgs_documentation-03","section":"fgs_documentation","group":"FGS Documentation","discipline":"documentation","color":"#aa249d","title":"Aircraft Jacket Files","moduleArea":"documentation","moduleId":"records","definition":"Maintain retrievable maintenance history and controlled supporting records for each aircraft.","proof":"Find the governing record, verify currency, reconcile missing items and preserve historical evidence.","pitfall":"Discarding a historical record because a new electronic entry exists.","scenario":"The aircraft transfers units and a required prior modification record cannot be located.","fundamentals":["Identify controlled current copies and retain required history.","Make corrections with before-and-after values, reason, authorizing basis and supporting evidence.","Transfer continuing obligations with the aircraft or organization."],"related":[{"id":"D16","name":"Control document versions","proof":"Identify the controlled record and resolve obsolete or conflicting copies while preserving required history."},{"id":"D17","name":"Amend records transparently","proof":"Preserve the original entry, correction, reason, authority, and supporting evidence when a record must be amended."},{"id":"D18","name":"Preserve history through transfers","proof":"Carry outstanding obligations and relevant accomplishment history when a person or asset changes organizations or locations."}],"mission":4,"advanced":"doc:home","refNames":["DAFI 21-101 Ch. 5 and Ch. 14","AFI 21-101 ACCSUP Ch. 14"],"status":"source-based + working-group synthesis (not official certification)"},{"id":"fgs_documentation-04","section":"fgs_documentation","group":"FGS Documentation","discipline":"documentation","color":"#aa249d","title":"Depot Inputs","moduleArea":"documentation","moduleId":"handoff","definition":"Package the correct pre-depot configuration, due work, unresolved discrepancies and supporting documentation.","proof":"Assemble a complete, accurate handover with open actions, evidence and return requirements.","pitfall":"Submitting a clean package that quietly omits an overdue requirement.","scenario":"A depot package lists two incomplete modifications as finished.","fundamentals":["Assemble open requirements, completed evidence, pending exceptions, due dates and owners.","Keep current records available and apply approved retention rules and holds.","Explain unresolved issues and the next action, rather than passing on an ambiguous green dashboard."],"related":[{"id":"D19","name":"Produce a usable handover","proof":"Assemble a retrievable package showing status, evidence, open issues, and continuing responsibilities."},{"id":"D20","name":"Apply retention and holds","proof":"Retain, freeze, archive, or dispose of records according to the supplied authorized rules and any applicable hold."}],"mission":4,"advanced":"doc:home","refNames":["DAFI 21-101 Ch. 5 and Ch. 14","AFI 21-101 ACCSUP Ch. 14"],"status":"source-based + working-group synthesis (not official certification)"},{"id":"fgs_documentation-05","section":"fgs_documentation","group":"FGS Documentation","discipline":"documentation","color":"#aa249d","title":"Time Change Items (TCI)","moduleArea":"documentation","moduleId":"forecast","definition":"Find and forecast item-specific limits based on correct time, cycle, calendar and configuration rules.","proof":"Identify upcoming due items by tail or serial and schedule work with parts and approved window.","pitfall":"Applying an aircraft calendar date to a component requiring cycles or hours.","scenario":"A component reaches a cycle limit sooner than its calendar date.","fundamentals":["Choose the correct calendar, flight-hour, cycle or event-based clock.","Use approved last accomplishment and interval to calculate the next due point.","Check prerequisites, parts, tools and qualification needs before asking Scheduling for downtime."],"related":[{"id":"D04","name":"Establish the due point","proof":"Calculate the deadline from the correct trigger, units, calendar, and authorized rule."},{"id":"D05","name":"Manage recurrence","proof":"Calculate the next obligation from the correct verified accomplishment or other anchor specified in the governing rule."},{"id":"D06","name":"Recognize prerequisites","proof":"Keep a dependent action open when the required predecessor or supporting evidence has not been established."}],"mission":4,"advanced":"doc:inspection","refNames":["DAFI 21-101 Ch. 5 and Ch. 14","AFI 21-101 ACCSUP Ch. 14"],"status":"source-based + working-group synthesis (not official certification)"},{"id":"fgs_documentation-06","section":"fgs_documentation","group":"FGS Documentation","discipline":"documentation","color":"#aa249d","title":"Time Compliance Technical Orders (TCTO)","moduleArea":"documentation","moduleId":"authority","definition":"Determine applicability, compliance window, needed actions and evidence for each TCTO.","proof":"Identify applicable affected tails, due points, kit/part needs and properly recorded completion.","pitfall":"Marking an order complete because the aircraft is not on the overdue report.","scenario":"A modification applies only to aircraft with an installed configuration variant.","fundamentals":["Find approved instructions and confirm revision, applicability and local supplements.","Translate the text into trigger, asset, due point, action and proof.","Check configuration, serial range, date and exceptions before loading work."],"related":[{"id":"D01","name":"Find the governing reference","proof":"Select the authoritative current instruction; recognize an obsolete, unofficial, or inapplicable substitute."},{"id":"D02","name":"Extract an actionable requirement","proof":"Translate prose into an action, trigger, deadline, responsible role, and evidence requirement."},{"id":"D03","name":"Determine applicability","proof":"Explain why an obligation applies or does not apply to the particular person, asset, configuration, or reporting period."}],"mission":4,"advanced":"doc:term","refNames":["DAFI 21-101 Ch. 5 and Ch. 14","AFI 21-101 ACCSUP Ch. 14"],"status":"source-based + working-group synthesis (not official certification)"},{"id":"fgs_documentation-07","section":"fgs_documentation","group":"FGS Documentation","discipline":"documentation","color":"#aa249d","title":"Special Inspections / TCI Management","moduleArea":"documentation","moduleId":"forecast","definition":"Control recurring special inspections and time-change forecasting so the schedule receives accurate demand.","proof":"Calculate each due point, verify status/evidence, identify overdue or missing records and push changes to Scheduling.","pitfall":"Treating the absence of an entry as proof that no requirement exists.","scenario":"The system is missing a required inspection generated by a recent technical change.","fundamentals":["Choose the correct calendar, flight-hour, cycle or event-based clock.","Use approved last accomplishment and interval to calculate the next due point.","Check prerequisites, parts, tools and qualification needs before asking Scheduling for downtime."],"related":[{"id":"D04","name":"Establish the due point","proof":"Calculate the deadline from the correct trigger, units, calendar, and authorized rule."},{"id":"D05","name":"Manage recurrence","proof":"Calculate the next obligation from the correct verified accomplishment or other anchor specified in the governing rule."},{"id":"D06","name":"Recognize prerequisites","proof":"Keep a dependent action open when the required predecessor or supporting evidence has not been established."}],"mission":4,"advanced":"doc:inspection","refNames":["DAFI 21-101 Ch. 5 and Ch. 14","AFI 21-101 ACCSUP Ch. 14"],"status":"source-based + working-group synthesis (not official certification)"},{"id":"fgs_documentation-08","section":"fgs_documentation","group":"FGS Documentation","discipline":"documentation","color":"#aa249d","title":"Configuration Management","moduleArea":"documentation","moduleId":"changes","definition":"Track approved aircraft/component configuration and understand how changes alter maintenance requirements.","proof":"Reconcile installed configuration, approved record, effective date and resulting new/retired tasks.","pitfall":"Loading a maintenance requirement for an aircraft where it does not apply.","scenario":"An upgrade changes the set of inspections required on eight aircraft.","fundamentals":["Check exception authority, scope, effective date and duration.","Determine what changed under a revision and which records must be updated or superseded.","Record unresolved conflicts and identify the approving authority."],"related":[{"id":"D14","name":"Handle exceptions","proof":"Recognize when a waiver or extension needs an authorized decision; record its scope, conditions, and expiration."},{"id":"D15","name":"Assess requirement changes","proof":"Identify the records affected by changed guidance and apply the supplied effective-date and transition rules."}],"mission":4,"advanced":"doc:term","refNames":["DAFI 21-101 Ch. 5 and Ch. 14","AFI 21-101 ACCSUP Ch. 14"],"status":"source-based + working-group synthesis (not official certification)"},{"id":"fgs_documentation-09","section":"fgs_documentation","group":"FGS Documentation","discipline":"documentation","color":"#aa249d","title":"MSM (local task label)","moduleArea":"documentation","moduleId":"records","definition":"Verify the meaning and governing workflow of this legacy/local task label before designing its official training process.","proof":"Locate the current task guide and demonstrate record reconciliation, routing, and traceable closeout.","pitfall":"Expanding an unverified acronym or inventing mandatory fields.","scenario":"A trainee is assigned an MSM product but cannot identify its controlling source.","fundamentals":["Identify controlled current copies and retain required history.","Make corrections with before-and-after values, reason, authorizing basis and supporting evidence.","Transfer continuing obligations with the aircraft or organization."],"related":[{"id":"D16","name":"Control document versions","proof":"Identify the controlled record and resolve obsolete or conflicting copies while preserving required history."},{"id":"D17","name":"Amend records transparently","proof":"Preserve the original entry, correction, reason, authority, and supporting evidence when a record must be amended."},{"id":"D18","name":"Preserve history through transfers","proof":"Carry outstanding obligations and relevant accomplishment history when a person or asset changes organizations or locations."}],"mission":4,"advanced":"doc:home","refNames":["DAFI 21-101 Ch. 5 and Ch. 14","AFI 21-101 ACCSUP Ch. 14"],"status":"source-based + working-group synthesis (not official certification)"},{"id":"fgs_documentation-10","section":"fgs_documentation","group":"FGS Documentation","discipline":"documentation","color":"#aa249d","title":"REMIS","moduleArea":"documentation","moduleId":"records","definition":"Understand the reporting and maintenance-history data relevant to the assigned REMIS workflow.","proof":"Reconcile identity, source events, authorized reporting periods and correction traceability.","pitfall":"Assuming a transmitted record matches the authoritative maintenance source.","scenario":"An asset-history report lacks a recent authorized equipment transfer.","fundamentals":["Identify controlled current copies and retain required history.","Make corrections with before-and-after values, reason, authorizing basis and supporting evidence.","Transfer continuing obligations with the aircraft or organization."],"related":[{"id":"D16","name":"Control document versions","proof":"Identify the controlled record and resolve obsolete or conflicting copies while preserving required history."},{"id":"D17","name":"Amend records transparently","proof":"Preserve the original entry, correction, reason, authority, and supporting evidence when a record must be amended."},{"id":"D18","name":"Preserve history through transfers","proof":"Carry outstanding obligations and relevant accomplishment history when a person or asset changes organizations or locations."}],"mission":4,"advanced":"doc:home","refNames":["DAFI 21-101 Ch. 5 and Ch. 14","AFI 21-101 ACCSUP Ch. 14"],"status":"source-based + working-group synthesis (not official certification)"},{"id":"wing_documentation-01","section":"wing_documentation","group":"Wing Documentation","discipline":"documentation","color":"#aa249d","title":"Wing TCTO Management","moduleArea":"documentation","moduleId":"changes","definition":"Integrate TCTO applicability, availability, kits, progress and due windows across a fleet.","proof":"Produce a defensible wing-wide status forecast with blocked, completed and due tails, plus source evidence.","pitfall":"Reporting 100% complete based on a count that includes non-applicable aircraft.","scenario":"Three tails lack parts for a deadline that affects next month’s flying schedule.","fundamentals":["Check exception authority, scope, effective date and duration.","Determine what changed under a revision and which records must be updated or superseded.","Record unresolved conflicts and identify the approving authority."],"related":[{"id":"D14","name":"Handle exceptions","proof":"Recognize when a waiver or extension needs an authorized decision; record its scope, conditions, and expiration."},{"id":"D15","name":"Assess requirement changes","proof":"Identify the records affected by changed guidance and apply the supplied effective-date and transition rules."}],"mission":4,"advanced":"doc:term","refNames":["DAFI 21-101 Ch. 5 and Ch. 14","AFI 21-101 ACCSUP Ch. 14"],"status":"source-based + working-group synthesis (not official certification)"},{"id":"wing_documentation-02","section":"wing_documentation","group":"Wing Documentation","discipline":"documentation","color":"#aa249d","title":"Job Master Listing (JML)","moduleArea":"documentation","moduleId":"jml","definition":"Translate controlled maintenance requirements into accurate scheduled job records and verify the load.","proof":"Validate requirement→applicability→JML entry→schedule→actual completion, including duplicate and missing jobs.","pitfall":"Loading a job without checking whether it applies or closing it without accomplishment evidence.","scenario":"A new TCTO applies to 12 aircraft but the JML has 11 and one duplicate.","fundamentals":["Identify the correct JML entry or work-control record and detect missing, duplicate or obsolete entries.","Check asset applicability, revision, due point, open status and responsible organization.","Define what completion evidence will actually prove accomplishment; route issues to the right authority."],"related":[{"id":"D07","name":"Route work correctly","proof":"Identify who performs, approves, verifies, and owns follow-up; preserve the distinction among those responsibilities."},{"id":"D08","name":"Define acceptable evidence","proof":"State what would establish completion before accepting a checkbox, signature, attachment, or status label."},{"id":"D09","name":"Match evidence to the obligation","proof":"Verify the person or asset, requirement, version, period, and scope; detect evidence that belongs to a different obligation."}],"mission":4,"advanced":"doc:home","refNames":["DAFI 21-101 Ch. 5 and Ch. 14","AFI 21-101 ACCSUP Ch. 14"],"status":"source-based + working-group synthesis (not official certification)"},{"id":"wing_documentation-03","section":"wing_documentation","group":"Wing Documentation","discipline":"documentation","color":"#aa249d","title":"120-Day TCTO Slide","moduleArea":"documentation","moduleId":"forecast","definition":"Communicate upcoming TCTO milestones and risks with a future-focused 120-day horizon.","proof":"Prepare a status view showing due dates, affected fleet, kits, capacity, risks and decisions needed.","pitfall":"Presenting only past completions with no next-action forecast.","scenario":"A fleet TCTO is due in 90 days; no kit is yet staged for six tails.","fundamentals":["Choose the correct calendar, flight-hour, cycle or event-based clock.","Use approved last accomplishment and interval to calculate the next due point.","Check prerequisites, parts, tools and qualification needs before asking Scheduling for downtime."],"related":[{"id":"D04","name":"Establish the due point","proof":"Calculate the deadline from the correct trigger, units, calendar, and authorized rule."},{"id":"D05","name":"Manage recurrence","proof":"Calculate the next obligation from the correct verified accomplishment or other anchor specified in the governing rule."},{"id":"D06","name":"Recognize prerequisites","proof":"Keep a dependent action open when the required predecessor or supporting evidence has not been established."}],"mission":4,"advanced":"doc:inspection","refNames":["DAFI 21-101 Ch. 5 and Ch. 14","AFI 21-101 ACCSUP Ch. 14"],"status":"source-based + working-group synthesis (not official certification)"},{"id":"wing_documentation-04","section":"wing_documentation","group":"Wing Documentation","discipline":"documentation","color":"#aa249d","title":"Quality Assurance (QA)","moduleArea":"documentation","moduleId":"closeout","definition":"Use independent verification and correct evidence before certifying documentation quality.","proof":"Spot missing signatures/evidence, erroneous applicability or inconsistent records and route accountable fixes.","pitfall":"Treating an audit pass rate as substitute for checking the actual critical entries.","scenario":"A record says closed but its supporting work document is incomplete.","fundamentals":["Distinguish a request, scheduled work, actual execution, verified accomplishment and authorized closeout.","Evaluate records and supporting evidence, including partial work and continuing restrictions.","Escalate incomplete or unsupported records instead of marking everything finished."],"related":[{"id":"D10","name":"Distinguish workflow states","proof":"Keep requested, scheduled, approved, performed, verified, and closed states separate when the exercise requires them."},{"id":"D11","name":"Verify closeout","proof":"Check the required completion details and authorized sign-off against the stated evidence standard before reporting completion."},{"id":"D12","name":"Handle partial accomplishment","proof":"Close supported portions while keeping unfinished obligations and their remaining requirements visible."},{"id":"D13","name":"Control unresolved work","proof":"Assign missing evidence or unfinished actions an owner, next action, due date, and recheck point."}],"mission":4,"advanced":"doc:home","refNames":["DAFI 21-101 Ch. 5 and Ch. 14","AFI 21-101 ACCSUP Ch. 14"],"status":"source-based + working-group synthesis (not official certification)"},{"id":"wing_documentation-05","section":"wing_documentation","group":"Wing Documentation","discipline":"documentation","color":"#aa249d","title":"Wing Configuration Management","moduleArea":"documentation","moduleId":"changes","definition":"Keep fleet configuration baselines consistent across modifications, records and scheduling requirements.","proof":"Reconcile version differences and detect maintenance requirements changed by new configurations.","pitfall":"Assuming all aircraft of one type share an identical configuration.","scenario":"A software/physical modification applies to one block and not another.","fundamentals":["Check exception authority, scope, effective date and duration.","Determine what changed under a revision and which records must be updated or superseded.","Record unresolved conflicts and identify the approving authority."],"related":[{"id":"D14","name":"Handle exceptions","proof":"Recognize when a waiver or extension needs an authorized decision; record its scope, conditions, and expiration."},{"id":"D15","name":"Assess requirement changes","proof":"Identify the records affected by changed guidance and apply the supplied effective-date and transition rules."}],"mission":4,"advanced":"doc:term","refNames":["DAFI 21-101 Ch. 5 and Ch. 14","AFI 21-101 ACCSUP Ch. 14"],"status":"source-based + working-group synthesis (not official certification)"},{"id":"wing_documentation-06","section":"wing_documentation","group":"Wing Documentation","discipline":"documentation","color":"#aa249d","title":"Wing Jacket Files","moduleArea":"documentation","moduleId":"records","definition":"Standardize and verify fleet maintenance histories and continuity through transfers and reviews.","proof":"Audit completeness and retrievability of key records across a sample of aircraft.","pitfall":"Treating a digital list as proof the underlying source records exist.","scenario":"A wing transfer inspection finds mismatches between jacket files and system history.","fundamentals":["Identify controlled current copies and retain required history.","Make corrections with before-and-after values, reason, authorizing basis and supporting evidence.","Transfer continuing obligations with the aircraft or organization."],"related":[{"id":"D16","name":"Control document versions","proof":"Identify the controlled record and resolve obsolete or conflicting copies while preserving required history."},{"id":"D17","name":"Amend records transparently","proof":"Preserve the original entry, correction, reason, authority, and supporting evidence when a record must be amended."},{"id":"D18","name":"Preserve history through transfers","proof":"Carry outstanding obligations and relevant accomplishment history when a person or asset changes organizations or locations."}],"mission":4,"advanced":"doc:home","refNames":["DAFI 21-101 Ch. 5 and Ch. 14","AFI 21-101 ACCSUP Ch. 14"],"status":"source-based + working-group synthesis (not official certification)"},{"id":"wing_documentation-07","section":"wing_documentation","group":"Wing Documentation","discipline":"documentation","color":"#aa249d","title":"Wing MSM (local label)","moduleArea":"documentation","moduleId":"handoff","definition":"Identify the current definition and workflow for the unit's MSM task and teach source-based quality control.","proof":"Demonstrate timely, complete, authorized product preparation after the meaning is verified.","pitfall":"Teaching an invented acronym expansion as official policy.","scenario":"The wing asks for MSM before an assessment but the product owner and source are unclear.","fundamentals":["Assemble open requirements, completed evidence, pending exceptions, due dates and owners.","Keep current records available and apply approved retention rules and holds.","Explain unresolved issues and the next action, rather than passing on an ambiguous green dashboard."],"related":[{"id":"D19","name":"Produce a usable handover","proof":"Assemble a retrievable package showing status, evidence, open issues, and continuing responsibilities."},{"id":"D20","name":"Apply retention and holds","proof":"Retain, freeze, archive, or dispose of records according to the supplied authorized rules and any applicable hold."}],"mission":4,"advanced":"doc:home","refNames":["DAFI 21-101 Ch. 5 and Ch. 14","AFI 21-101 ACCSUP Ch. 14"],"status":"source-based + working-group synthesis (not official certification)"},{"id":"wing_documentation-08","section":"wing_documentation","group":"Wing Documentation","discipline":"documentation","color":"#aa249d","title":"Out-of-Cycle Request","moduleArea":"documentation","moduleId":"changes","definition":"Assess and route an exceptional maintenance or reporting change outside the normal schedule.","proof":"State reason, scope, approval authority, mission impact and resulting record changes.","pitfall":"Treating a request as approval or skipping required coordination.","scenario":"An urgent mission requires moving work from the approved weekly plan.","fundamentals":["Check exception authority, scope, effective date and duration.","Determine what changed under a revision and which records must be updated or superseded.","Record unresolved conflicts and identify the approving authority."],"related":[{"id":"D14","name":"Handle exceptions","proof":"Recognize when a waiver or extension needs an authorized decision; record its scope, conditions, and expiration."},{"id":"D15","name":"Assess requirement changes","proof":"Identify the records affected by changed guidance and apply the supplied effective-date and transition rules."}],"mission":4,"advanced":"doc:term","refNames":["DAFI 21-101 Ch. 5 and Ch. 14","AFI 21-101 ACCSUP Ch. 14"],"status":"source-based + working-group synthesis (not official certification)"},{"id":"fgs_analysis-01","section":"fgs_analysis","group":"FGS Analysis","discipline":"analysis","color":"#1f5aa9","title":"Health of the Fleet (HOF)","moduleArea":"analysis","moduleId":"brief","definition":"Translate aircraft availability, recurring problems, inspections and trends into a credible fleet-health narrative.","proof":"Give the commander a sourced snapshot of current capability, principal drivers, near-term risks and recommended decisions.","pitfall":"Calling the fleet healthy solely because one headline rate is green.","scenario":"MC improves while three aircraft approach Phase together and repeat faults increase.","fundamentals":["Forecast fleet capability against flying or maintenance requirements and stress-test assumptions.","Compare countermeasures, costs, opportunities and adverse consequences.","Brief the decision, confidence, risks and sources; check whether action improved the result."],"related":[{"id":"A17","name":"Assess and project capability against requirements","proof":"Prepare an annual capability assessment using resources, anticipated availability, limiting constraints, and explicit assumptions; estimate feasible output, identify requirement gaps, and present plausible scenarios."},{"id":"A18","name":"Compare options and test sensitivity","proof":"Compare proposed actions and tradeoffs; determine whether the preferred action changes when important assumptions, constraints, or estimates change."},{"id":"A19","name":"Brief results and defend recommendations","proof":"Prepare and defend a health-of-fleet or equivalent briefing that connects current condition, output, trends, drivers, uncertainty, forecast risks, and required decisions using traceable evidence."},{"id":"A20","name":"Verify the result of action","proof":"Define success before acting; compare subsequent evidence on a valid basis and revise the recommendation when results or assumptions change."}],"mission":5,"advanced":"analysis:sim6","refNames":["ACCI 21-118 (2018 archive)","DAFI 21-101 Ch. 5 and Ch. 14"],"status":"source-based + working-group synthesis (not official certification)"},{"id":"fgs_analysis-02","section":"fgs_analysis","group":"FGS Analysis","discipline":"analysis","color":"#1f5aa9","title":"MAJCOM reports Numbers","moduleArea":"analysis","moduleId":"rates","definition":"Apply correct reporting definitions, populations and formulas to maintenance metrics used in the MAJCOM reports process.","proof":"Reconcile numerators, denominators, rates, period and aircraft population to source records.","pitfall":"Using sortie counts as the denominator for every maintenance rate.","scenario":"Two of ten breaks are fixed inside eight hours; determine the proper 8-hour fix rate.","fundamentals":["Identify count versus rate; use approved definitions and compatible units.","Compute break rate from qualifying breaks and flights; fix rate from quick repairs and qualifying breaks; repeat rate from repeats and PRDs; CANN rate from cann actions and flights.","Roll up by summing appropriate numerators and denominators, not by blindly averaging percentages.","Reconcile daily, weekly and monthly reports to the underlying source."],"related":[{"id":"A03","name":"Define and calculate the right metric","proof":"Recognize measurement type and meaning; specify numerator, eligible denominator, exposure, units, and approved formula. Distinguish a status snapshot from activity accumulated during a period."},{"id":"A04","name":"Aggregate and roll up correctly","proof":"Pool eligible counts or apply justified weights; produce valid group and period summaries without averaging incompatible percentages or double-counting overlapping periods."},{"id":"A05","name":"Produce and reconcile recurring reports","proof":"Provide daily, weekly, monthly, and annual numbers with consistent definitions and cutoffs; reconcile source detail with published totals and explain late entries, revisions, or unresolved differences."}],"mission":5,"advanced":"analysis:metric","refNames":["ACCI 21-118 (2018 archive)","DAFI 21-101 Ch. 5 and Ch. 14"],"status":"source-based + working-group synthesis (not official certification)"},{"id":"fgs_analysis-03","section":"fgs_analysis","group":"FGS Analysis","discipline":"analysis","color":"#1f5aa9","title":"Special Studies","moduleArea":"analysis","moduleId":"drivers","definition":"Investigate a focused operational question using valid data, alternatives and independent checks.","proof":"Define the problem, select measures, isolate candidate drivers, evaluate hypotheses and produce useful recommendations.","pitfall":"Declaring a root cause based on the first correlation found.","scenario":"One unit shows rising downtime; distinguish supply delays from repeat maintenance failures.","fundamentals":["Locate which subsystems, aircraft or causes account for the observed burden.","Separate verified facts from hypotheses and alternatives.","Use a fishbone and plan a test that could falsify the favored explanation."],"related":[{"id":"A11","name":"Identify and report contributing drivers","proof":"Separate relevant groups and quantify their contributions to lost time, changed output, or other results; report concentrations and case-mix changes while distinguishing measured contributors from suspected causes."},{"id":"A12","name":"Present evidence honestly","proof":"Choose suitable displays with clear populations, periods, units, denominators, labels, and scales; make the important comparison understandable without distortion."},{"id":"A13","name":"Develop testable explanations","proof":"Distinguish association from cause, consider alternatives, and use a fishbone or similar investigation structure; turn suspected causes into predictions and identify evidence that could support or contradict them."}],"mission":5,"advanced":"analysis:sim4","refNames":["ACCI 21-118 (2018 archive)","DAFI 21-101 Ch. 5 and Ch. 14"],"status":"source-based + working-group synthesis (not official certification)"},{"id":"fgs_analysis-04","section":"fgs_analysis","group":"FGS Analysis","discipline":"analysis","color":"#1f5aa9","title":"Daily Numbers","moduleArea":"analysis","moduleId":"rates","definition":"Reconcile daily production and maintenance data without losing scope, timing or source definitions.","proof":"Prepare a correct daily report and identify unusual shifts and missing data requiring review.","pitfall":"Mixing yesterday's completions with today's open records.","scenario":"The daily rate falls while the number of sorties doubles.","fundamentals":["Identify count versus rate; use approved definitions and compatible units.","Compute break rate from qualifying breaks and flights; fix rate from quick repairs and qualifying breaks; repeat rate from repeats and PRDs; CANN rate from cann actions and flights.","Roll up by summing appropriate numerators and denominators, not by blindly averaging percentages.","Reconcile daily, weekly and monthly reports to the underlying source."],"related":[{"id":"A03","name":"Define and calculate the right metric","proof":"Recognize measurement type and meaning; specify numerator, eligible denominator, exposure, units, and approved formula. Distinguish a status snapshot from activity accumulated during a period."},{"id":"A04","name":"Aggregate and roll up correctly","proof":"Pool eligible counts or apply justified weights; produce valid group and period summaries without averaging incompatible percentages or double-counting overlapping periods."},{"id":"A05","name":"Produce and reconcile recurring reports","proof":"Provide daily, weekly, monthly, and annual numbers with consistent definitions and cutoffs; reconcile source detail with published totals and explain late entries, revisions, or unresolved differences."}],"mission":5,"advanced":"analysis:metric","refNames":["ACCI 21-118 (2018 archive)","DAFI 21-101 Ch. 5 and Ch. 14"],"status":"source-based + working-group synthesis (not official certification)"},{"id":"fgs_analysis-05","section":"fgs_analysis","group":"FGS Analysis","discipline":"analysis","color":"#1f5aa9","title":"Weekly Numbers","moduleArea":"analysis","moduleId":"trends","definition":"Aggregate daily data into a consistent week and identify a useful signal.","proof":"Recompute totals, compatible rates and changes from the previous week; explain unusual events.","pitfall":"Taking an average of daily percentages with different denominators.","scenario":"Three high-volume days and two low-volume days show similar percentages; compute the true weekly rate.","fundamentals":["Plot comparable measures over time and mark changes in definition.","Set an evidence-based baseline or candidate standard from valid historical data.","Look for sustained patterns and ask whether the signal is operationally meaningful."],"related":[{"id":"A08","name":"Read change over time","proof":"Examine trends, persistence, recurring cycles, and workload changes; distinguish a sustained pattern from an isolated period."},{"id":"A09","name":"Establish historical baselines and propose standards","proof":"Use representative historical data to establish a baseline and propose a defensible benchmark or performance standard; explain limitations and distinguish observed performance, proposed targets, and authorized requirements."},{"id":"A10","name":"Evaluate apparent signals","proof":"Monitor variation against an appropriate baseline and stated decision rule; identify results requiring investigation without treating the signal as an established cause."}],"mission":5,"advanced":"analysis:sim2","refNames":["ACCI 21-118 (2018 archive)","DAFI 21-101 Ch. 5 and Ch. 14"],"status":"source-based + working-group synthesis (not official certification)"},{"id":"fgs_analysis-06","section":"fgs_analysis","group":"FGS Analysis","discipline":"analysis","color":"#1f5aa9","title":"Monthly Numbers","moduleArea":"analysis","moduleId":"trends","definition":"Produce consistent monthly maintenance performance indicators and explain operational drivers.","proof":"Reconcile the full month, validate the reporting template and provide evidence-based comments.","pitfall":"Turning a one-time spike into an unsupported trend claim.","scenario":"One squadron has a poor month after multiple Phase entries.","fundamentals":["Plot comparable measures over time and mark changes in definition.","Set an evidence-based baseline or candidate standard from valid historical data.","Look for sustained patterns and ask whether the signal is operationally meaningful."],"related":[{"id":"A08","name":"Read change over time","proof":"Examine trends, persistence, recurring cycles, and workload changes; distinguish a sustained pattern from an isolated period."},{"id":"A09","name":"Establish historical baselines and propose standards","proof":"Use representative historical data to establish a baseline and propose a defensible benchmark or performance standard; explain limitations and distinguish observed performance, proposed targets, and authorized requirements."},{"id":"A10","name":"Evaluate apparent signals","proof":"Monitor variation against an appropriate baseline and stated decision rule; identify results requiring investigation without treating the signal as an established cause."}],"mission":5,"advanced":"analysis:sim2","refNames":["ACCI 21-118 (2018 archive)","DAFI 21-101 Ch. 5 and Ch. 14"],"status":"source-based + working-group synthesis (not official certification)"},{"id":"fgs_analysis-07","section":"fgs_analysis","group":"FGS Analysis","discipline":"analysis","color":"#1f5aa9","title":"Annual Numbers","moduleArea":"analysis","moduleId":"compare","definition":"Interpret longer-term performance while accounting for fleet changes, flying exposure and changes in metric definitions.","proof":"Build comparable annual totals/rates and a documented explanatory narrative.","pitfall":"Comparing unlike fleet populations or changed formulas across years.","scenario":"An aircraft unit changes inventory size midyear; calculate a fair annual comparison.","fundamentals":["Compare similar populations, aircraft types, time periods and missions.","Inspect outliers, spread, zeros, and missing values before summarizing.","Make assumptions explicit and use rates or exposure-adjusted values when necessary."],"related":[{"id":"A06","name":"Make comparable comparisons","proof":"Check definitions, periods, exposure, workloads, and populations; repair or qualify a comparison whose basis differs."},{"id":"A07","name":"Inspect the distribution","proof":"Examine spread, tails, and unusual cases; recognize when an average conceals an operationally important concentration or delay."}],"mission":5,"advanced":"analysis:sim3","refNames":["ACCI 21-118 (2018 archive)","DAFI 21-101 Ch. 5 and Ch. 14"],"status":"source-based + working-group synthesis (not official certification)"},{"id":"wing_analysis-01","section":"wing_analysis","group":"Wing Analysis","discipline":"analysis","color":"#17637e","title":"MAJCOM reports Collection","moduleArea":"analysis","moduleId":"rates","definition":"Coordinate and validate wing-wide data submissions before the command report is built.","proof":"Reconcile required contributors, timelines, populations, source reports and completeness.","pitfall":"Collecting everyone's spreadsheets without checking conflicting totals.","scenario":"Two squadrons submit totals with different cutoff dates.","fundamentals":["Identify count versus rate; use approved definitions and compatible units.","Compute break rate from qualifying breaks and flights; fix rate from quick repairs and qualifying breaks; repeat rate from repeats and PRDs; CANN rate from cann actions and flights.","Roll up by summing appropriate numerators and denominators, not by blindly averaging percentages.","Reconcile daily, weekly and monthly reports to the underlying source."],"related":[{"id":"A03","name":"Define and calculate the right metric","proof":"Recognize measurement type and meaning; specify numerator, eligible denominator, exposure, units, and approved formula. Distinguish a status snapshot from activity accumulated during a period."},{"id":"A04","name":"Aggregate and roll up correctly","proof":"Pool eligible counts or apply justified weights; produce valid group and period summaries without averaging incompatible percentages or double-counting overlapping periods."},{"id":"A05","name":"Produce and reconcile recurring reports","proof":"Provide daily, weekly, monthly, and annual numbers with consistent definitions and cutoffs; reconcile source detail with published totals and explain late entries, revisions, or unresolved differences."}],"mission":5,"advanced":"analysis:metric","refNames":["ACCI 21-118 (2018 archive)","DAFI 21-101 Ch. 5 and Ch. 14"],"status":"source-based + working-group synthesis (not official certification)"},{"id":"wing_analysis-02","section":"wing_analysis","group":"Wing Analysis","discipline":"analysis","color":"#17637e","title":"MAJCOM reports Comments","moduleArea":"analysis","moduleId":"brief","definition":"Explain the causal hypotheses, data limitations, drivers and actions behind reported values.","proof":"Write specific, evidence-linked comments stating what changed, why it may have changed, and what action is next.","pitfall":"Writing 'rate decreased due to maintenance' without supporting evidence.","scenario":"A monthly MC rate drops and leadership needs an actionable explanation.","fundamentals":["Forecast fleet capability against flying or maintenance requirements and stress-test assumptions.","Compare countermeasures, costs, opportunities and adverse consequences.","Brief the decision, confidence, risks and sources; check whether action improved the result."],"related":[{"id":"A17","name":"Assess and project capability against requirements","proof":"Prepare an annual capability assessment using resources, anticipated availability, limiting constraints, and explicit assumptions; estimate feasible output, identify requirement gaps, and present plausible scenarios."},{"id":"A18","name":"Compare options and test sensitivity","proof":"Compare proposed actions and tradeoffs; determine whether the preferred action changes when important assumptions, constraints, or estimates change."},{"id":"A19","name":"Brief results and defend recommendations","proof":"Prepare and defend a health-of-fleet or equivalent briefing that connects current condition, output, trends, drivers, uncertainty, forecast risks, and required decisions using traceable evidence."},{"id":"A20","name":"Verify the result of action","proof":"Define success before acting; compare subsequent evidence on a valid basis and revise the recommendation when results or assumptions change."}],"mission":5,"advanced":"analysis:sim6","refNames":["ACCI 21-118 (2018 archive)","DAFI 21-101 Ch. 5 and Ch. 14"],"status":"source-based + working-group synthesis (not official certification)"},{"id":"wing_analysis-03","section":"wing_analysis","group":"Wing Analysis","discipline":"analysis","color":"#17637e","title":"Wing HOF","moduleArea":"analysis","moduleId":"brief","definition":"Combine multiple unit views into decision-quality wing-wide fleet health assessment.","proof":"Identify capability risks, clustered inspections, top repeat discrepancies, shortages and options.","pitfall":"Averaging unit performance percentages without considering size and mission.","scenario":"One unit is improving but another has critical fleet readiness constraints.","fundamentals":["Forecast fleet capability against flying or maintenance requirements and stress-test assumptions.","Compare countermeasures, costs, opportunities and adverse consequences.","Brief the decision, confidence, risks and sources; check whether action improved the result."],"related":[{"id":"A17","name":"Assess and project capability against requirements","proof":"Prepare an annual capability assessment using resources, anticipated availability, limiting constraints, and explicit assumptions; estimate feasible output, identify requirement gaps, and present plausible scenarios."},{"id":"A18","name":"Compare options and test sensitivity","proof":"Compare proposed actions and tradeoffs; determine whether the preferred action changes when important assumptions, constraints, or estimates change."},{"id":"A19","name":"Brief results and defend recommendations","proof":"Prepare and defend a health-of-fleet or equivalent briefing that connects current condition, output, trends, drivers, uncertainty, forecast risks, and required decisions using traceable evidence."},{"id":"A20","name":"Verify the result of action","proof":"Define success before acting; compare subsequent evidence on a valid basis and revise the recommendation when results or assumptions change."}],"mission":5,"advanced":"analysis:sim6","refNames":["ACCI 21-118 (2018 archive)","DAFI 21-101 Ch. 5 and Ch. 14"],"status":"source-based + working-group synthesis (not official certification)"},{"id":"wing_analysis-04","section":"wing_analysis","group":"Wing Analysis","discipline":"analysis","color":"#17637e","title":"Wing First Look","moduleArea":"analysis","moduleId":"question","definition":"Test whether the commander’s next-period plan is achievable against fleet and maintenance realities.","proof":"Provide early assessment of likely capability, risks, caveats, and missing information.","pitfall":"Briefing an optimistic projection without verifying constraints.","scenario":"The wing requests a 20% flying increase while dock capacity is unchanged.","fundamentals":["Identify the commander’s intended decision and credible alternatives.","Define the assets, dates, events and exclusions that answer that question.","Ask which records or operational participants can validate the data."],"related":[{"id":"A01","name":"Frame the decision","proof":"Translate a request into a decision, responsible audience, relevant alternatives, and the evidence needed to distinguish them."},{"id":"A02","name":"Define the population and evidence coverage","proof":"Establish the population, period, and exclusions; identify missing cases, selection effects, or reporting gaps that limit the conclusion."}],"mission":5,"advanced":"analysis:home","refNames":["ACCI 21-118 (2018 archive)","DAFI 21-101 Ch. 5 and Ch. 14"],"status":"source-based + working-group synthesis (not official certification)"},{"id":"wing_analysis-05","section":"wing_analysis","group":"Wing Analysis","discipline":"analysis","color":"#17637e","title":"AGE Daily","moduleArea":"analysis","moduleId":"rates","definition":"Track support-equipment readiness as part of the maintenance capability picture.","proof":"Report relevant equipment limitations, operational impact and timely source-based changes.","pitfall":"Ignoring a critical AGE shortage because aircraft metrics are green.","scenario":"Only one functioning tester supports three simultaneous maintenance events.","fundamentals":["Identify count versus rate; use approved definitions and compatible units.","Compute break rate from qualifying breaks and flights; fix rate from quick repairs and qualifying breaks; repeat rate from repeats and PRDs; CANN rate from cann actions and flights.","Roll up by summing appropriate numerators and denominators, not by blindly averaging percentages.","Reconcile daily, weekly and monthly reports to the underlying source."],"related":[{"id":"A03","name":"Define and calculate the right metric","proof":"Recognize measurement type and meaning; specify numerator, eligible denominator, exposure, units, and approved formula. Distinguish a status snapshot from activity accumulated during a period."},{"id":"A04","name":"Aggregate and roll up correctly","proof":"Pool eligible counts or apply justified weights; produce valid group and period summaries without averaging incompatible percentages or double-counting overlapping periods."},{"id":"A05","name":"Produce and reconcile recurring reports","proof":"Provide daily, weekly, monthly, and annual numbers with consistent definitions and cutoffs; reconcile source detail with published totals and explain late entries, revisions, or unresolved differences."}],"mission":5,"advanced":"analysis:metric","refNames":["ACCI 21-118 (2018 archive)","DAFI 21-101 Ch. 5 and Ch. 14"],"status":"source-based + working-group synthesis (not official certification)"},{"id":"wing_analysis-06","section":"wing_analysis","group":"Wing Analysis","discipline":"analysis","color":"#17637e","title":"Wing Special Studies","moduleArea":"analysis","moduleId":"drivers","definition":"Perform cross-unit investigations with a defined decision question and fair comparisons.","proof":"Produce reproducible analyses with alternatives, context and recommendation for leadership.","pitfall":"Claiming unit A is worse because it has more breaks without accounting for sorties.","scenario":"Two wings have different sortie exposures and reported maintenance totals.","fundamentals":["Locate which subsystems, aircraft or causes account for the observed burden.","Separate verified facts from hypotheses and alternatives.","Use a fishbone and plan a test that could falsify the favored explanation."],"related":[{"id":"A11","name":"Identify and report contributing drivers","proof":"Separate relevant groups and quantify their contributions to lost time, changed output, or other results; report concentrations and case-mix changes while distinguishing measured contributors from suspected causes."},{"id":"A12","name":"Present evidence honestly","proof":"Choose suitable displays with clear populations, periods, units, denominators, labels, and scales; make the important comparison understandable without distortion."},{"id":"A13","name":"Develop testable explanations","proof":"Distinguish association from cause, consider alternatives, and use a fishbone or similar investigation structure; turn suspected causes into predictions and identify evidence that could support or contradict them."}],"mission":5,"advanced":"analysis:sim4","refNames":["ACCI 21-118 (2018 archive)","DAFI 21-101 Ch. 5 and Ch. 14"],"status":"source-based + working-group synthesis (not official certification)"},{"id":"wing_analysis-07","section":"wing_analysis","group":"Wing Analysis","discipline":"analysis","color":"#17637e","title":"Wing QA","moduleArea":"analysis","moduleId":"compare","definition":"Use quality evidence to determine recurring process or record problems and their impact.","proof":"Validate audit sample, error classification, recurrence and recommended preventive control.","pitfall":"Treating a small unrepresentative QA sample as definitive.","scenario":"Recurring documentation defects follow an apparent process change.","fundamentals":["Compare similar populations, aircraft types, time periods and missions.","Inspect outliers, spread, zeros, and missing values before summarizing.","Make assumptions explicit and use rates or exposure-adjusted values when necessary."],"related":[{"id":"A06","name":"Make comparable comparisons","proof":"Check definitions, periods, exposure, workloads, and populations; repair or qualify a comparison whose basis differs."},{"id":"A07","name":"Inspect the distribution","proof":"Examine spread, tails, and unusual cases; recognize when an average conceals an operationally important concentration or delay."}],"mission":5,"advanced":"analysis:sim3","refNames":["ACCI 21-118 (2018 archive)","DAFI 21-101 Ch. 5 and Ch. 14"],"status":"source-based + working-group synthesis (not official certification)"},{"id":"wing_analysis-08","section":"wing_analysis","group":"Wing Analysis","discipline":"analysis","color":"#17637e","title":"Attrition","moduleArea":"analysis","moduleId":"trends","definition":"Track changes in operational inventory or capability and explain how they change forecasts and reported measures.","proof":"Separate inventory changes, operational impacts and applicable reporting periods.","pitfall":"Comparing flying production before/after an attrition event without adjusting capacity.","scenario":"A fleet loses two aircraft and its yearly utilization target remains unchanged.","fundamentals":["Plot comparable measures over time and mark changes in definition.","Set an evidence-based baseline or candidate standard from valid historical data.","Look for sustained patterns and ask whether the signal is operationally meaningful."],"related":[{"id":"A08","name":"Read change over time","proof":"Examine trends, persistence, recurring cycles, and workload changes; distinguish a sustained pattern from an isolated period."},{"id":"A09","name":"Establish historical baselines and propose standards","proof":"Use representative historical data to establish a baseline and propose a defensible benchmark or performance standard; explain limitations and distinguish observed performance, proposed targets, and authorized requirements."},{"id":"A10","name":"Evaluate apparent signals","proof":"Monitor variation against an appropriate baseline and stated decision rule; identify results requiring investigation without treating the signal as an established cause."}],"mission":5,"advanced":"analysis:sim2","refNames":["ACCI 21-118 (2018 archive)","DAFI 21-101 Ch. 5 and Ch. 14"],"status":"source-based + working-group synthesis (not official certification)"},{"id":"wing_analysis-09","section":"wing_analysis","group":"Wing Analysis","discipline":"analysis","color":"#17637e","title":"COMACC Slide / Leadership Brief","moduleArea":"analysis","moduleId":"brief","definition":"Present reliable indicators, significant drivers, forecast risk and a defensible action to senior leaders.","proof":"Deliver a concise brief that withstands denominator, source and alternative-explanation questions.","pitfall":"Overstating certainty or using charts that disguise an unresolved data-quality issue.","scenario":"A skeptical commander asks which two actions would have the most supportable effect.","fundamentals":["Forecast fleet capability against flying or maintenance requirements and stress-test assumptions.","Compare countermeasures, costs, opportunities and adverse consequences.","Brief the decision, confidence, risks and sources; check whether action improved the result."],"related":[{"id":"A17","name":"Assess and project capability against requirements","proof":"Prepare an annual capability assessment using resources, anticipated availability, limiting constraints, and explicit assumptions; estimate feasible output, identify requirement gaps, and present plausible scenarios."},{"id":"A18","name":"Compare options and test sensitivity","proof":"Compare proposed actions and tradeoffs; determine whether the preferred action changes when important assumptions, constraints, or estimates change."},{"id":"A19","name":"Brief results and defend recommendations","proof":"Prepare and defend a health-of-fleet or equivalent briefing that connects current condition, output, trends, drivers, uncertainty, forecast risks, and required decisions using traceable evidence."},{"id":"A20","name":"Verify the result of action","proof":"Define success before acting; compare subsequent evidence on a valid basis and revise the recommendation when results or assumptions change."}],"mission":5,"advanced":"analysis:sim6","refNames":["ACCI 21-118 (2018 archive)","DAFI 21-101 Ch. 5 and Ch. 14"],"status":"source-based + working-group synthesis (not official certification)"},{"id":"engine-01","section":"engine","group":"Engine Management","discipline":"engine","color":"#9b4515","title":"Hush House","moduleArea":"scheduling","moduleId":"capacity","definition":"Coordinate engine test-facility demand, shared resources and work dependencies in the maintenance plan.","proof":"Show authorized facility time, prerequisites, conflicts, available support and contingency.","pitfall":"Double-booking a test facility or assuming the maintenance event is complete after the slot is reserved.","scenario":"Two engines need test runs during a single available facility window.","fundamentals":["Map bottlenecks: inspection docks, specialist labor, tools, parts, facility restrictions and shared assets.","Preserve required reserves, dependencies and protected windows; identify donor/recovery effects when an aircraft is unavailable.","Quantify the mission impact of moving work and offer choices when demand exceeds capacity."],"related":[{"id":"S14","name":"Plan use and recovery of unavailable resources","proof":"In a cann-bird case with multiple parts delays, compare keeping, recovering, or using an eligible donor; assess total capability, required authority, added work, parts dependencies, and the donor recovery plan."},{"id":"S16","name":"Protect bottlenecks and make capacity tradeoffs","proof":"Identify the resource limiting output; compare feasible allocations against stated priorities and report the system-wide gain, unmet demand, displaced work, and consequences."}],"mission":3,"advanced":"scheduling:skill8","refNames":["DAFI 21-101 Ch. 5 and Ch. 14","AFI 21-101 ACCSUP Ch. 14"],"status":"source-based + working-group synthesis (not official certification)"},{"id":"engine-02","section":"engine","group":"Engine Management","discipline":"engine","color":"#9b4515","title":"Bump: CDAT, CEMS, IMDS","moduleArea":"integrity","moduleId":"reconcile","definition":"Keep engine status/configuration and related maintenance records synchronized across designated systems, subject to authorized local processes.","proof":"Trace one event through source record, system status, correction authority and downstream verification.","pitfall":"Editing all systems to match a guess rather than proving the correct value.","scenario":"An engine removal appears in one system but not in the others.","fundamentals":["Check for orphan references and one-sided missing records.","Compare matching records field by field against the approved source.","Flag every discrepancy before deciding which can be corrected."],"related":[{"id":"I11","name":"Detect broken references","proof":"Find records pointing to nonexistent or incorrect people, assets, organizations, or parent transactions."},{"id":"I12","name":"Reconcile membership both ways","proof":"Identify required records absent from the actual set and unexpected records present in it; investigate before deciding a correction."},{"id":"I13","name":"Reconcile matched attributes","proof":"After identity matches, check the relevant dates, roles, permissions, quantities, and statuses for agreement with evidence."}],"mission":6,"advanced":"integrity:skill4","refNames":["DAFI 21-101 Ch. 5 and Ch. 14","AFI 21-101 ACCSUP Ch. 14"],"status":"source-based + working-group synthesis (not official certification)"},{"id":"engine-03","section":"engine","group":"Engine Management","discipline":"engine","color":"#9b4515","title":"Inspection Forecasting","moduleArea":"documentation","moduleId":"forecast","definition":"Forecast engine inspections and components using serial-specific utilization and controlling life/inspection limits.","proof":"Show upcoming inspections by engine serial, due criteria, planned window and readiness risk.","pitfall":"Using an aircraft forecast as proof an installed engine has the same due point.","scenario":"An engine will reach a time limit sooner after a higher planned flying rate.","fundamentals":["Choose the correct calendar, flight-hour, cycle or event-based clock.","Use approved last accomplishment and interval to calculate the next due point.","Check prerequisites, parts, tools and qualification needs before asking Scheduling for downtime."],"related":[{"id":"D04","name":"Establish the due point","proof":"Calculate the deadline from the correct trigger, units, calendar, and authorized rule."},{"id":"D05","name":"Manage recurrence","proof":"Calculate the next obligation from the correct verified accomplishment or other anchor specified in the governing rule."},{"id":"D06","name":"Recognize prerequisites","proof":"Keep a dependent action open when the required predecessor or supporting evidence has not been established."}],"mission":4,"advanced":"doc:inspection","refNames":["DAFI 21-101 Ch. 5 and Ch. 14","AFI 21-101 ACCSUP Ch. 14"],"status":"source-based + working-group synthesis (not official certification)"},{"id":"engine-04","section":"engine","group":"Engine Management","discipline":"engine","color":"#9b4515","title":"Waivers Needed","moduleArea":"documentation","moduleId":"changes","definition":"Identify an exception requiring authorized review before an engine/work requirement can proceed.","proof":"State need, justification, applicable limit, operational risk, owner and decision authority.","pitfall":"Treating an expiring limit as automatically waived when request paperwork exists.","scenario":"An inspection cannot be accomplished before the planned sortie surge.","fundamentals":["Check exception authority, scope, effective date and duration.","Determine what changed under a revision and which records must be updated or superseded.","Record unresolved conflicts and identify the approving authority."],"related":[{"id":"D14","name":"Handle exceptions","proof":"Recognize when a waiver or extension needs an authorized decision; record its scope, conditions, and expiration."},{"id":"D15","name":"Assess requirement changes","proof":"Identify the records affected by changed guidance and apply the supplied effective-date and transition rules."}],"mission":4,"advanced":"doc:term","refNames":["DAFI 21-101 Ch. 5 and Ch. 14","AFI 21-101 ACCSUP Ch. 14"],"status":"source-based + working-group synthesis (not official certification)"},{"id":"engine-05","section":"engine","group":"Engine Management","discipline":"engine","color":"#9b4515","title":"Waivers Processed","moduleArea":"documentation","moduleId":"closeout","definition":"Verify actual approval, scope, dates and restrictions of waiver decisions before relying on them.","proof":"Reconcile approved or denied status to the correct engine/requirement and communicate limits.","pitfall":"Confusing requested, recommended and approved status.","scenario":"The waiver has approval for one serial but planners applied it to three.","fundamentals":["Distinguish a request, scheduled work, actual execution, verified accomplishment and authorized closeout.","Evaluate records and supporting evidence, including partial work and continuing restrictions.","Escalate incomplete or unsupported records instead of marking everything finished."],"related":[{"id":"D10","name":"Distinguish workflow states","proof":"Keep requested, scheduled, approved, performed, verified, and closed states separate when the exercise requires them."},{"id":"D11","name":"Verify closeout","proof":"Check the required completion details and authorized sign-off against the stated evidence standard before reporting completion."},{"id":"D12","name":"Handle partial accomplishment","proof":"Close supported portions while keeping unfinished obligations and their remaining requirements visible."},{"id":"D13","name":"Control unresolved work","proof":"Assign missing evidence or unfinished actions an owner, next action, due date, and recheck point."}],"mission":4,"advanced":"doc:home","refNames":["DAFI 21-101 Ch. 5 and Ch. 14","AFI 21-101 ACCSUP Ch. 14"],"status":"source-based + working-group synthesis (not official certification)"},{"id":"engine-06","section":"engine","group":"Engine Management","discipline":"engine","color":"#9b4515","title":"Meetings","moduleArea":"scheduling","moduleId":"recover","definition":"Use engine-management meetings to coordinate accurate fleet status, due work and resource decisions.","proof":"Enter with current serial-by-serial status and leave with actions, owners and deadlines.","pitfall":"Showing slides without a resourced executable action plan.","scenario":"An engine shortage requires prioritizing two competing missions.","fundamentals":["Identify exactly what changed: ETIC, part arrival, mission demand, manpower or aircraft status.","Recompute what can fly, what can be maintained and what must move; distinguish feasible from desired output.","Coordinate with Production, Operations, MOC and specialists; capture alternatives, owners and due actions."],"related":[{"id":"S17","name":"Recover a disrupted schedule","proof":"After an outage, late part, changed requirement, or duration overrun, trace dependencies, test contingencies, restore feasibility, and communicate necessary changes while preserving unaffected commitments."},{"id":"S18","name":"Run a scheduling meeting that produces decisions","proof":"Prepare the plan and unresolved issues, reconcile stakeholder requirements, surface conflicts, record decisions and tradeoffs, and assign owners, deadlines, and follow-up actions."}],"mission":2,"advanced":"scheduling:skill8","refNames":["DAFI 21-101 Ch. 5 and Ch. 14","AFI 21-101 ACCSUP Ch. 14"],"status":"source-based + working-group synthesis (not official certification)"},{"id":"engine-07","section":"engine","group":"Engine Management","discipline":"engine","color":"#9b4515","title":"Shared Resources","moduleArea":"scheduling","moduleId":"capacity","definition":"Schedule common engine tools, facilities, crews and parts without hidden conflicts.","proof":"Show resource usage, maintenance dependencies, alternate options and critical risks.","pitfall":"Assuming equipment is available because it is not shown on the aircraft checkerboard.","scenario":"A shared tester is booked at the same time for two engines.","fundamentals":["Map bottlenecks: inspection docks, specialist labor, tools, parts, facility restrictions and shared assets.","Preserve required reserves, dependencies and protected windows; identify donor/recovery effects when an aircraft is unavailable.","Quantify the mission impact of moving work and offer choices when demand exceeds capacity."],"related":[{"id":"S14","name":"Plan use and recovery of unavailable resources","proof":"In a cann-bird case with multiple parts delays, compare keeping, recovering, or using an eligible donor; assess total capability, required authority, added work, parts dependencies, and the donor recovery plan."},{"id":"S16","name":"Protect bottlenecks and make capacity tradeoffs","proof":"Identify the resource limiting output; compare feasible allocations against stated priorities and report the system-wide gain, unmet demand, displaced work, and consequences."}],"mission":3,"advanced":"scheduling:skill8","refNames":["DAFI 21-101 Ch. 5 and Ch. 14","AFI 21-101 ACCSUP Ch. 14"],"status":"source-based + working-group synthesis (not official certification)"},{"id":"engine-08","section":"engine","group":"Engine Management","discipline":"engine","color":"#9b4515","title":"MXG Group Meeting","moduleArea":"scheduling","moduleId":"recover","definition":"Translate engine fleet status into concise group-level risk and decision requests.","proof":"Brief available engines, upcoming inspections, mission impact, options and ownership.","pitfall":"Reporting only total engines without serviceability and forecast context.","scenario":"The group asks how many engines will be available next week and what might change that number.","fundamentals":["Identify exactly what changed: ETIC, part arrival, mission demand, manpower or aircraft status.","Recompute what can fly, what can be maintained and what must move; distinguish feasible from desired output.","Coordinate with Production, Operations, MOC and specialists; capture alternatives, owners and due actions."],"related":[{"id":"S17","name":"Recover a disrupted schedule","proof":"After an outage, late part, changed requirement, or duration overrun, trace dependencies, test contingencies, restore feasibility, and communicate necessary changes while preserving unaffected commitments."},{"id":"S18","name":"Run a scheduling meeting that produces decisions","proof":"Prepare the plan and unresolved issues, reconcile stakeholder requirements, surface conflicts, record decisions and tradeoffs, and assign owners, deadlines, and follow-up actions."}],"mission":2,"advanced":"scheduling:skill8","refNames":["DAFI 21-101 Ch. 5 and Ch. 14","AFI 21-101 ACCSUP Ch. 14"],"status":"source-based + working-group synthesis (not official certification)"},{"id":"engine-09","section":"engine","group":"Engine Management","discipline":"engine","color":"#9b4515","title":"Engine HOF","moduleArea":"analysis","moduleId":"brief","definition":"Explain engine fleet health using valid status, inspection flow, reliability and support indicators.","proof":"Produce a serial-level source-backed forecast and principal risk summary.","pitfall":"Relying on one FMC count that conceals clustered removals or overdue items.","scenario":"Three engines are ready today but all have near-term inspections.","fundamentals":["Forecast fleet capability against flying or maintenance requirements and stress-test assumptions.","Compare countermeasures, costs, opportunities and adverse consequences.","Brief the decision, confidence, risks and sources; check whether action improved the result."],"related":[{"id":"A17","name":"Assess and project capability against requirements","proof":"Prepare an annual capability assessment using resources, anticipated availability, limiting constraints, and explicit assumptions; estimate feasible output, identify requirement gaps, and present plausible scenarios."},{"id":"A18","name":"Compare options and test sensitivity","proof":"Compare proposed actions and tradeoffs; determine whether the preferred action changes when important assumptions, constraints, or estimates change."},{"id":"A19","name":"Brief results and defend recommendations","proof":"Prepare and defend a health-of-fleet or equivalent briefing that connects current condition, output, trends, drivers, uncertainty, forecast risks, and required decisions using traceable evidence."},{"id":"A20","name":"Verify the result of action","proof":"Define success before acting; compare subsequent evidence on a valid basis and revise the recommendation when results or assumptions change."}],"mission":5,"advanced":"analysis:sim6","refNames":["DAFI 21-101 Ch. 5 and Ch. 14","AFI 21-101 ACCSUP Ch. 14"],"status":"source-based + working-group synthesis (not official certification)"},{"id":"engine-10","section":"engine","group":"Engine Management","discipline":"engine","color":"#9b4515","title":"Weekly Scheduling MXG","moduleArea":"scheduling","moduleId":"checkerboard","definition":"Reconcile engine work with the wing’s approved weekly aircraft and facility plans.","proof":"Integrate removals, installs, testing, parts, capability and needed approvals.","pitfall":"Moving engine work without updating the affected flying plan.","scenario":"An engine swap conflicts with a scheduled high-priority sortie.","fundamentals":["Convert annual, monthly and weekly flying requirements into daily demand and required availability.","Mark known downtime, overdue or approaching inspections, Phase windows, depot moves, NMC status, manpower, parts and facilities.","Find usable maintenance opportunities; group work that can share access, downtime or setup without violating instructions.","Condense compatible PFR and PBG work so a common cure happens once only when authorized. Preserve two workdays per task and a full 24-hour cure."],"related":[{"id":"S01","name":"Translate requirements across planning horizons","proof":"Convert annual, quarterly, monthly, or weekly requirements into daily demand; reconcile the detailed schedule with required output rather than treating each planning period as a separate skill."},{"id":"S02","name":"Establish the planning picture and constraints","proof":"Verify availability, requirements, source dates, and estimates; distinguish confirmed facts, assumptions, mandatory limits, and negotiable preferences before allocating work."},{"id":"S06","name":"Build an integrated schedule","proof":"Build a checkerboard showing flying, reserve, maintenance, and unavailable periods; synchronize people, aircraft, tools, space, and capacity without conflicting assignments."},{"id":"S08","name":"Find and use genuine scheduling opportunities","proof":"Inspect idle windows and holes; fit eligible work after checking duration, dependencies, capability, and resources, and recognize when a gap must remain unfilled."},{"id":"S09","name":"Combine compatible work and reduce setup","proof":"Compare bundles and sequences that reduce repeated access, setup, changeovers, downtime, or cure only when supplied instructions permit; preserve every requirement and verify the actual time or capacity saved."}],"mission":1,"advanced":"scheduling:skill7","refNames":["DAFI 21-101 Ch. 5 and Ch. 14","AFI 21-101 ACCSUP Ch. 14"],"status":"source-based + working-group synthesis (not official certification)"},{"id":"engine-11","section":"engine","group":"Engine Management","discipline":"engine","color":"#9b4515","title":"OG / MXG Coordination","moduleArea":"scheduling","moduleId":"recover","definition":"Explain the operational consequences of engine-management decisions to Operations and Maintenance leaders.","proof":"Offer choices that quantify mission effects, prerequisites, risk and decision authority.","pitfall":"Saying 'cannot support' without showing a recoverable option.","scenario":"Operations requests an extra mission that depends on a limited serviceable engine.","fundamentals":["Identify exactly what changed: ETIC, part arrival, mission demand, manpower or aircraft status.","Recompute what can fly, what can be maintained and what must move; distinguish feasible from desired output.","Coordinate with Production, Operations, MOC and specialists; capture alternatives, owners and due actions."],"related":[{"id":"S17","name":"Recover a disrupted schedule","proof":"After an outage, late part, changed requirement, or duration overrun, trace dependencies, test contingencies, restore feasibility, and communicate necessary changes while preserving unaffected commitments."},{"id":"S18","name":"Run a scheduling meeting that produces decisions","proof":"Prepare the plan and unresolved issues, reconcile stakeholder requirements, surface conflicts, record decisions and tradeoffs, and assign owners, deadlines, and follow-up actions."}],"mission":2,"advanced":"scheduling:skill8","refNames":["DAFI 21-101 Ch. 5 and Ch. 14","AFI 21-101 ACCSUP Ch. 14"],"status":"source-based + working-group synthesis (not official certification)"},{"id":"dit_dbm-01","section":"dit_dbm","group":"Data Integrity / DBM","discipline":"dit_dbm","color":"#ae249d","title":"User Access","moduleArea":"dbm","moduleId":"access","definition":"Give users only approved access, roles and scope they need for the work, then review its continued need.","proof":"Verify requester identity, approval, correct role/scope, audit and later removal.","pitfall":"Copying the permissions of the most powerful user to solve a convenience problem.","scenario":"A trainee asks for administrator access to view a single report.","fundamentals":["Verify request, approving authority, required role and exact scope.","Grant only necessary permissions and test the intended user task.","Review effective access periodically and remove permissions after departure or reassignment."],"related":[{"id":"B04","name":"Translate duties into permissions","proof":"Build a role and scope matrix that permits approved work without unnecessary access."},{"id":"B05","name":"Provision authorized access","proof":"Link the correct identity, approved request, account, and permission scope; perform or route the action within assigned authority."},{"id":"B06","name":"Manage account lifecycle changes","proof":"Update access for arrivals, changed duties, departures, and expirations without accumulating obsolete permissions."},{"id":"B07","name":"Review effective access","proof":"Compare actual permissions, including supplied group inheritance, with current approvals and investigate discrepancies."},{"id":"B08","name":"Test access behavior","proof":"Verify that an authorized task succeeds and a specified unauthorized action remains restricted."}],"mission":7,"advanced":"dbm:skill1","refNames":["DAFI 21-101 Ch. 5 and Ch. 14","AFI 21-101 ACCSUP Ch. 14"],"status":"source-based + working-group synthesis (not official certification)"},{"id":"dit_dbm-02","section":"dit_dbm","group":"Data Integrity / DBM","discipline":"dit_dbm","color":"#ae249d","title":"Data Integrity Team (DIT)","moduleArea":"integrity","moduleId":"authority","definition":"Protect maintenance data truthfulness and investigate source-versus-system disagreements.","proof":"Audit for accuracy, completeness, uniqueness, timing and provenance; document findings and accountable corrections.","pitfall":"Correcting a mismatch by guesswork without source evidence.","scenario":"A system shows 'inspected' while the approved source shows a valve was replaced.","fundamentals":["Identify the approved source for each field and its effective date.","Match stable aircraft, person or event identifiers instead of relying on a name.","Align report scope, unit and time period."],"related":[{"id":"I01","name":"Establish source authority","proof":"Identify the authoritative source for each field, including the applicable version and effective date."},{"id":"I02","name":"Establish record identity","proof":"Use stable identifiers for people, equipment, and events; investigate ambiguous identities instead of relying on matching names."},{"id":"I03","name":"Align scope and timing","proof":"Confirm that extracts cover the intended population and compatible dates before treating their differences as errors."}],"mission":6,"advanced":"integrity:skill2","refNames":["DAFI 21-101 Ch. 5 and Ch. 14","AFI 21-101 ACCSUP Ch. 14"],"status":"source-based + working-group synthesis (not official certification)"},{"id":"dit_dbm-03","section":"dit_dbm","group":"Data Integrity / DBM","discipline":"dit_dbm","color":"#ae249d","title":"Subsystem Access","moduleArea":"dbm","moduleId":"access","definition":"Apply access scopes to the right application, subsystem, organization and task.","proof":"Demonstrate correct least-privilege grant with validation that the user can do the approved task only.","pitfall":"Granting permissions across unrelated units or records.","scenario":"A person can view one subsystem but needs an approved role in another.","fundamentals":["Verify request, approving authority, required role and exact scope.","Grant only necessary permissions and test the intended user task.","Review effective access periodically and remove permissions after departure or reassignment."],"related":[{"id":"B04","name":"Translate duties into permissions","proof":"Build a role and scope matrix that permits approved work without unnecessary access."},{"id":"B05","name":"Provision authorized access","proof":"Link the correct identity, approved request, account, and permission scope; perform or route the action within assigned authority."},{"id":"B06","name":"Manage account lifecycle changes","proof":"Update access for arrivals, changed duties, departures, and expirations without accumulating obsolete permissions."},{"id":"B07","name":"Review effective access","proof":"Compare actual permissions, including supplied group inheritance, with current approvals and investigate discrepancies."},{"id":"B08","name":"Test access behavior","proof":"Verify that an authorized task succeeds and a specified unauthorized action remains restricted."}],"mission":7,"advanced":"dbm:skill1","refNames":["DAFI 21-101 Ch. 5 and Ch. 14","AFI 21-101 ACCSUP Ch. 14"],"status":"source-based + working-group synthesis (not official certification)"},{"id":"dit_dbm-04","section":"dit_dbm","group":"Data Integrity / DBM","discipline":"dit_dbm","color":"#ae249d","title":"Wing System Improvement","moduleArea":"dbm","moduleId":"change","definition":"Identify recurring defects in workflows or systems and manage an authorized change with verification.","proof":"Define user impact, root cause, proposed control, approval, test case and rollback plan.","pitfall":"Deploying a change without proving it addresses the problem or can be reversed.","scenario":"A report consistently hides an aircraft status due to a filter default.","fundamentals":["Identify affected settings, users and downstream interfaces.","Back up and test in a controlled environment when applicable.","Implement with approval, verify workflow, and preserve rollback/evidence."],"related":[{"id":"B14","name":"Control configuration changes","proof":"Assess affected workflows, obtain required authorization, test a scoped change, and preserve the previous configuration."},{"id":"B15","name":"Verify restoration and rollback","proof":"Demonstrate that a backup or rollback restores the required records, configuration, and usable workflow."}],"mission":7,"advanced":"dbm:skill5","refNames":["DAFI 21-101 Ch. 5 and Ch. 14","AFI 21-101 ACCSUP Ch. 14"],"status":"source-based + working-group synthesis (not official certification)"},{"id":"dit_dbm-05","section":"dit_dbm","group":"Data Integrity / DBM","discipline":"dit_dbm","color":"#ae249d","title":"System Release Improvement","moduleArea":"dbm","moduleId":"change","definition":"Test and release a configuration/software improvement while protecting live records and continuity.","proof":"Document pre-change baseline, test, approval, deployment, rollback and post-change user verification.","pitfall":"Releasing a fix that solves one report but breaks imports.","scenario":"A new import mapping passes one test row but duplicates records after release.","fundamentals":["Identify affected settings, users and downstream interfaces.","Back up and test in a controlled environment when applicable.","Implement with approval, verify workflow, and preserve rollback/evidence."],"related":[{"id":"B14","name":"Control configuration changes","proof":"Assess affected workflows, obtain required authorization, test a scoped change, and preserve the previous configuration."},{"id":"B15","name":"Verify restoration and rollback","proof":"Demonstrate that a backup or rollback restores the required records, configuration, and usable workflow."}],"mission":7,"advanced":"dbm:skill5","refNames":["DAFI 21-101 Ch. 5 and Ch. 14","AFI 21-101 ACCSUP Ch. 14"],"status":"source-based + working-group synthesis (not official certification)"},{"id":"dit_dbm-06","section":"dit_dbm","group":"Data Integrity / DBM","discipline":"dit_dbm","color":"#ae249d","title":"User Troubleshooting","moduleArea":"dbm","moduleId":"troubleshoot","definition":"Diagnose whether a complaint comes from access, filtering, bad data, an interface or a system outage.","proof":"Reproduce the complaint, isolate the layer, perform authorized fix/escalation, then rerun the task.","pitfall":"Resetting accounts or editing records before determining the actual cause.","scenario":"Three users cannot see a record for three different reasons.","fundamentals":["Reproduce the user task and expected output.","Check report filters and view scope, then data presence and permission.","Examine interface logs, error states and recent changes to locate the failing layer."],"related":[{"id":"B09","name":"Locate the failing layer","proof":"Use evidence to distinguish identity, permission, configuration, interface, application, or underlying service problems."},{"id":"B10","name":"Diagnose misleading views","proof":"Check filters, periods, scope, refresh state, and report settings before treating absent output as absent data."},{"id":"B11","name":"Reconstruct an incident","proof":"Correlate timestamps, transaction identifiers, logs, and user actions into a supported sequence of events."}],"mission":7,"advanced":"dbm:skill3","refNames":["DAFI 21-101 Ch. 5 and Ch. 14","AFI 21-101 ACCSUP Ch. 14"],"status":"source-based + working-group synthesis (not official certification)"},{"id":"dit_dbm-07","section":"dit_dbm","group":"Data Integrity / DBM","discipline":"dit_dbm","color":"#ae249d","title":"Update DIT PowerPoint","moduleArea":"integrity","moduleId":"prevent","definition":"Turn recurring data-quality findings into concise trends, impacts and action-oriented briefings.","proof":"Show evidence, scale of defect, corrected/unresolved records, causes and preventive controls.","pitfall":"Reporting only errors found without separating confirmed fixes and open uncertainties.","scenario":"Monthly discrepancies drop but one critical record remains unresolved.","fundamentals":["Assign unresolved cases an owner and seek additional evidence or authority.","Identify recurring patterns and propose source validation rules or training fixes.","Retest controls on new examples and monitor whether the defect returns."],"related":[{"id":"I19","name":"Manage unresolved exceptions","proof":"Keep unresolved discrepancies, including conflicting current sources, with an owner and follow-up; obtain the needed evidence or authorized decision instead of inventing a value."},{"id":"I20","name":"Prevent recurring errors","proof":"Turn recurring defects into appropriate validation or reconciliation controls and demonstrate that those controls catch the intended problem."}],"mission":6,"advanced":"integrity:skill10","refNames":["DAFI 21-101 Ch. 5 and Ch. 14","AFI 21-101 ACCSUP Ch. 14"],"status":"source-based + working-group synthesis (not official certification)"},{"id":"dit_dbm-08","section":"dit_dbm","group":"Data Integrity / DBM","discipline":"dit_dbm","color":"#ae249d","title":"User Help & Training","moduleArea":"dbm","moduleId":"workflow","definition":"Teach users accurate workflows, safe system use and where to get authoritative help.","proof":"Provide task-based guidance, a realistic exercise, appropriate escalation and evidence of task completion.","pitfall":"Telling people which buttons to press without teaching why/when a record is valid.","scenario":"A new user repeatedly miscodes the same record because the local guide is unclear.","fundamentals":["Define the user problem, expected workflow and acceptance condition.","Map key fields, identifiers, relationships and approved reference settings.","Check how a configuration change affects reports and downstream systems."],"related":[{"id":"B01","name":"Define the supported workflow","proof":"Translate an approved business need into users, inputs, operations, outputs, and observable acceptance conditions."},{"id":"B02","name":"Structure information for the workflow","proof":"Define necessary entities, identifiers, fields, relationships, and permitted values without needlessly duplicating the same fact."},{"id":"B03","name":"Maintain reference configuration","proof":"Apply approved changes to organizational units, resource categories, codes, or settings and verify the affected workflows."}],"mission":7,"advanced":"dbm:skill3","refNames":["DAFI 21-101 Ch. 5 and Ch. 14","AFI 21-101 ACCSUP Ch. 14"],"status":"source-based + working-group synthesis (not official certification)"}],"additions":[{"discipline":"scheduling","title":"Aircraft Capability vs Mission Need","module":"scheduling.daily","why":"Proposed shared foundational skill: distinguish FMC status from mission-specific capability; never schedule solely by a green status."},{"discipline":"scheduling","title":"Unplanned Breaks & Recovery","module":"scheduling.recover","why":"Proposed: rebuild flying and maintenance plans after NMCM/NMCS, part delays, launch aborts, or priority changes."},{"discipline":"scheduling","title":"90-Day Checkerboard Capstone","module":"scheduling.checkerboard","why":"Proposed: create, execute, revise and defend a 90-day fleet plan with real capacity limits."},{"discipline":"analysis","title":"Metric Denominators & Data Sources","module":"analysis.rates","why":"Proposed: compute break/fix/repeat/cann rates from raw events and document definitions."},{"discipline":"analysis","title":"Trends, Correlation & Root Cause","module":"analysis.drivers","why":"Proposed: separate signal from noise, test alternative causes and avoid unsupported causation."},{"discipline":"documentation","title":"Applicability → JML → Evidence","module":"documentation.jml","why":"Proposed: make an independent requirement/load/closeout audit with no invented completion evidence."},{"discipline":"documentation","title":"Cure and Combined Downtime","module":"documentation.forecast","why":"Proposed synthetic lesson: sequence PFR/PBG and required cure under supplied instructions; coordinate with Scheduling."},{"discipline":"engine","title":"Serial-Level Engine Control","module":"integrity.reconcile","why":"Proposed: follow one engine through installed, serviceable, restricted, removed and returned status."},{"discipline":"dit_dbm","title":"Independent Multi-Record Audit","module":"integrity.reconcile","why":"Proposed: find missing, duplicated, stale, inconsistent and correctly matching records without hints."},{"discipline":"dit_dbm","title":"Interface Failure and Recovery","module":"dbm.interface","why":"Proposed: distinguish mappings, accepted/rejected transactions, access and visibility, then verify recovery."},{"discipline":"all","title":"Communication and Decision Defense","module":"analysis.brief","why":"Shared competency: explain assumption, evidence, risk, alternatives and authorized action to a skeptical leader."},{"discipline":"all","title":"Delayed Retention & Supervisor Check","module":"scheduling.control","why":"Shared competency: repeat an unfamiliar case later; a game score alone never grants official qualification."}],"sources":{"CAFI 21-165 (historical CAF scheduling)":{"url":"https://static.e-publishing.af.mil/production/1/moodyafb/publication/combatairforceinstruction21-165_moodyafbsup/combat_air_force_instruction_21-165_moodyafbsup.pdf","note":"2015 Moody AFB supplement citing 2013 CAFI 21-165; archival reference, not confirmed current."},"AFI 21-101 ACCSUP Ch. 14":{"url":"https://static.e-publishing.af.mil/production/1/acc/publication/afi21-101_accsup/afi21-101_accsup.pdf","note":"ACC supplement includes 2025 guidance memorandum; verify current publication and supersession before operational use."},"ACCI 21-118 (2018 archive)":{"url":"https://static.e-publishing.af.mil/production/1/acc/publication/acci21-118/acci21-118.pdf","note":"2018 PDF retrievable; a 2026 revision is catalogued elsewhere and must be checked before operational use."},"DAFI 21-101 Ch. 5 and Ch. 14":{"url":"https://static.e-publishing.af.mil/production/1/af_a4/publication/dafi21-101/dafi21-101.pdf","note":"Parent maintenance instruction; check current changes/guidance memoranda."}},"notes":["Original five-column task inventory transcribed from supplied image002.png; labels made readable while retaining FGS/Wing organization.","100 Skills Working Draft (11 Nov 2026) and FLUX workshop (17 Nov 2026) are draft training inputs, not approved qualification standards.","SUTE, MSM, AFTO 103, AF Forms 2407/2410 are retained as task labels; verify exact current procedures before treating description as authoritative.","Earlier “FGP” abbreviation was normalized to Flying Hour Program (FHP).","Historical 21-165 and 2018 21-118 are teaching/source background, not assertions of current compliance."]};
